INSERT INTO `quest_template_locale` (`ID`, `locale`, `LogTitle`, `LogDescription`, `QuestDescription`, `AreaDescription`, `PortraitGiverText`, `PortraitGiverName`, `PortraitTurnInText`, `PortraitTurnInName`, `QuestCompletionLog`, `VerifiedBuild`) VALUES
(66695, 'ruRU', 'Искушая судьбу: Гробница Предвечных', '', '', '', '', '', '', '', '', 45114),
(66694, 'ruRU', 'Искушая судьбу: Святилище Господства', '', '', '', '', '', '', '', '', 45114),
(66661, 'ruRU', 'Это просто монета, сколько она стоит?', 'Расспросите брокеров в Орибосе.', '<Этот любопытный предмет вызывает много вопросов, на которые у вас нет ответа. Как он к вам попал? Зачем он нужен? Опасен ли он?>\n\n<Если служители Вечного города не смогут вам помочь, брокеры должны что-то знать.>', '', '', '', '', '', '', 45114),
(66649, 'ruRU', 'Повернуть колесо', 'Победите $1oa разных боссов в судьбоносных рейдах.', '<Преодолев все испытания, вы чувствуете, что ваша сила растет. Какова бы ни была причина этих аномалий, они больше не сбивают вас с толку, а придают уверенности.>\n\n<Погрузитесь в неопределенность еще раз, бросьте вызов тьме – и возьмите свою судьбу в свои руки.>', '', '', '', '', '', '', 45114),
(66648, 'ruRU', 'Наперекор судьбе', 'Победите 30 разных боссов в судьбоносных рейдах.', '<Весь мир начинает кружиться вокруг вас. Ваши воспоминания об этом месте становятся туманными, подробности накладываются друг на друга. Что-то изменилось.>\n\n<Вы уверены, что при всем внешнем сходстве это не то место, которое вы знали. Это не совсем оно.>\n\n<Тем не менее надо идти вперед. Ни миражи, ни искажение реальности вас не остановят.>', '', '', '', '', '', '', 45114),
(66619, 'ruRU', 'Антрос', '', '', '', '', '', '', '', '', 45114),
(66618, 'ruRU', 'Мор\'гет', '', '', '', '', '', '', '', '', 45114),
(66420, 'ruRU', 'Перерыв на обед', 'Облейте морской водой 3 рабочих в Штормграде.', 'Товар мы вернули, а теперь пора закончить сортировку.\n\nИз-за всей этой передряги часть команды решила устроить себе долгий перерыв на обед.  Постарайся найти их и отправь сюда. \n\nПировать будем, когда закончим дела.', '', '', '', '', '', '', 45114),
(66390, 'ruRU', 'Украденная утварь', 'Заберите украденные товары у вора в порту Штормграда.', 'Эх! Эти просоленные Морские Косы уплыли в очередное путешествие, а меня оставили товары сортировать!\n\nМожет быть, это я от зависти злюсь, но почему Тони не могла все описать покороче? Мне нужны инструкции, а не книжная рукопись. Еще и часть товара пропала вместе с одним из рабочих! \n\nНе поможешь мне ее вернуть? Этот бездарь наверняка все вернет в обмен на выпивку. А если нет, окати его вот этим.', '', '', '', '', '', '', 45114),
(66383, 'ruRU', 'Легендарная помощь', 'Сходи к торговцу Просветленных Вило и посмотри, что есть на продажу.', '$n, мы убедили Просветленных брокеров заготовить побольше припасов для битвы с Тюремщиком!', '', '', '', '', '', '', 45114),
(66323, 'ruRU', 'Пирог для ленивых', 'Разбудите 3 рабочих в Оргриммаре.', 'Товар спасен, и мы можем завершить работу. Вот только все рабочие разбрелись по городу и отлынивают от дел. \n\nНайди, где они попрятались, и \"убеди\" поскорее вернуться сюда. Немного пирога в лицо, и они сразу оживятся.', '', '', '', '', '', '', 45114),
(66243, 'ruRU', 'Дар надежды', 'Встретьтесь с Шандрисой Оперенной Луной в Роще Пробуждения.', 'Приветствую тебя, пилигрим Утробы.\n\nУ меня послание от Королевы Зимы. Она просит тебя явиться на церемонию в Арденвельде, в которой участвуют и другие выходцы из твоего мира.\n\nШандриса Оперенная Луна – одна из них. Найди ее в Роще Пробуждения.', '', '', '', '', '', '', 45114),
(66170, 'ruRU', 'Молчаливое Бдение', 'Узрите видение Дори\'тур.', '<Дори\'тур беззвучно парит в воздухе и выжидающе смотрит на вас.\n\nПохоже, благородная сова хочет показать вам что-то важное.>', '', '', '', '', '', '', 45114),
(66091, 'ruRU', 'Путь темных следопытов', '', '', '', '', '', '', '', '', 45114),
(66090, 'ruRU', 'Путь темных следопытов', 'Примите регалии темного следопыта.', '', '', '', '', '', '', '', 45114),
(66042, 'ruRU', 'Закономерности в закономерностях', 'Помогайте союзникам в Зерет Мортисе, выполняя локальные и ежедневные задания, открывая сундуки с сокровищами и убивая редких существ.', 'Мы находимся у истоков Темных Земель. Нельзя позволить, чтобы это место стало орудием их уничтожения.\n\nПомоги нашим новым союзникам, $n. Их поддержка приблизит нас к успеху и поможет избежать гибели всего сущего.', '', '', '', '', '', '', 45114),
(65788, 'ruRU', 'Прогулка с призраками', 'Поговорите с Калией в тронном зале Лордерона.', 'Возвращение в эти руины многое значит для Отрекшихся. Нашему народу нужен был символ, который давал бы надежду и помогал продержаться в темные для нас времена. Особенно после окончания войны.\n\nЯ видела, как Калия шла к тронному залу. С ним связано много ее воспоминаний. Много призраков. \n\nЯ беспокоюсь за нее.', '', '', '', '', '', 'Встретьтесь с Калией в тронном зале Лордерона.', 45114),
(65774, 'ruRU', 'Пробуждение катализатора', 'Отправьтесь в Сады Катализации и примените катализатор творения.', 'Ты чувствуешь это, герой? Над Садами Катализации разносится гул катализатора творения, наполненного новой энергией. \n\nЭта сила может преобразить само мироздание. Скорее воспользуйся ею.', '', '', '', '', '', '', 45114),
(65764, 'ruRU', 'Гробница Предвечных – Бремя короны', 'Добудьте четыре осколка меча Андуина в Гробнице Предвечных в обычном режиме.', 'Клинок Андуина – мощный проводник для силы Тюремщика. Если мы добудем осколки этого оружия, я смогу открыть путь к юному королю.\n\nЧетырех будет достаточно. Так мы сможем навсегда освободить Андуина от гнета Тюремщика.', '', '', '', '', '', '', 45114),
(65763, 'ruRU', 'Гробница Предвечных – Бремя короны', 'Добудьте четыре осколка меча Андуина в Гробнице Предвечных в героическом режиме.', 'Клинок Андуина – мощный проводник для силы Тюремщика. Если мы добудем осколки этого оружия, я смогу открыть путь к юному королю.\n\nЧетырех будет достаточно. Так мы сможем навсегда освободить Андуина от гнета Тюремщика.', '', '', '', '', '', '', 45114),
(65762, 'ruRU', 'Гробница Предвечных – Бремя короны', 'Добудьте четыре осколка меча Андуина в Гробнице Предвечных в эпохальном режиме.', 'Клинок Андуина – мощный проводник для силы Тюремщика. Если мы добудем осколки этого оружия, я смогу открыть путь к юному королю.\n\nЧетырех будет достаточно. Так мы сможем навсегда освободить Андуина от гнета Тюремщика.', '', '', '', '', '', '', 45114),
(65732, 'ruRU', 'Терпеливый буфонид', '', 'Только посмотри на это чудесное создание Зерет Мортиса! Судя по хитрому блеску в глазах, оно все это время нас разыгрывало!\n\nТерпение приносит свои плоды. Бад доволен. \n\nОгромное спасибо, пилигрим.', '', '', '', '', '', '', 45114),
(65731, 'ruRU', 'Зарывшийся буфонид', '', '', '', '', '', '', '', '', 45114),
(65730, 'ruRU', 'Зарывшийся буфонид', '', '', '', '', '', '', '', '', 45114),
(65729, 'ruRU', 'Зарывшийся буфонид', '', '', '', '', '', '', '', '', 45114),
(65728, 'ruRU', 'Зарывшийся буфонид', '', '', '', '', '', '', '', '', 45114),
(65700, 'ruRU', 'Управление сердечником', 'Осмотрите любопытное существо у входа в пещеру Изгнанника.', 'Ты $gпришел:пришла; как нельзя кстати.\n\nТолько что в одну из моих ловушек попалось прелюбопытнейшее существо. Хотелось бы проверить, что это, но... оно может быть опасным. А тебя таким не испугаешь.\n\nИ Покопока с собой возьми. Вдруг удастся разгадать новую тайну?', '', '', '', '', '', '', 45114),
(65669, 'ruRU', 'Отчет для Седогрива', 'Доставьте письмо Калии Генну Седогриву в Орибос.', 'Спасибо за твою помощь, которая привела нас к этому историческому моменту.\n\nОстальным тоже будет интересно узнать, что здесь произошло. Доставь им это письмо с моими наилучшими пожеланиями.', '', '', '', '', '', '', 45114),
(65668, 'ruRU', 'Мрачный Совет', 'Понаблюдайте за созданием нового Мрачного Совета.', 'Знания и опыт каждого из нас помогли очистить поверхность Подгорода для Отрекшихся.\n\nМы добились этого только потому, что забыли про взаимное недоверие и поставили благо нашего народа на первое место. Пора официально закрепить наш совет.\n\nМы уже не та нежить, что служила и повиновалась Сильване Ветрокрылой. Теперь мы сами выбираем свою судьбу, с гордостью и независимостью, которые вернули себе когда-то вместе со свободой воли.\n\nВ новом будущем не место старым правителям.', '', '', '', '', '', '', 45114),
(65667, 'ruRU', 'Исцеление Лордерона', 'Сядьте на теневого нетопыря и разбросайте пожирателей чумы по руинам Лордерона.', 'Время пришло. Молюсь Свету, чтобы наш план сработал.\n\nПовозки мастера-аптекаря Фаранелла наштамповали множество таких же пожирателей чумы, и нетопыри готовы их разбросать.\n\nЕсли увидишь, куда надо запустить еще больше противоядия, подай сигнал ракетой.\n\nВзлети в небо и покончи с этой чумой. За Лордерон. За Отрекшихся.', '', '', '', '', '', 'Встретьтесь с Лилиан Восс во дворе руин Лордерона.', 45114),
(65666, 'ruRU', 'Возвращение в Брилл', 'Вернитесь к мастеру-аптекарю Фаранеллу около руин Лордерона.', 'Наш пожиратель чумы окреп и теперь может взяться за добычу намного крупнее.\n\nДавай отнесем его обратно Фаранеллу. Он сказал, что сможет скопировать его свойства и выпустить пожирателей чумы на руины.\n\nТогда у нас будет хоть и крошечный, но шанс снова заселить наш дом.\n\nВозьми мой камень возвращения. Он перенесет тебя обратно в Брилл.', '', '', '', '', '', '', 45114),
(65665, 'ruRU', 'Воплощение', 'Убейте лордеронскую чуму.', 'Какую гаденькую чуму ты мне $gпринес:принесла;, подмастерье. Ее состряпал настоящий садист.\n\nЯ придал образцу форму, чтобы изучить. Но неблагодарная тварь ни с того ни с сего набросилась на меня! \n\nА потом уползла дальше в дом Чумы. Печально, но придется ее уничтожить, пока не выросла еще сильнее... или крупнее.\n\nКое-какие плюсы тут все-таки есть. Если твой пожиратель чумы выживет, он приспособится именно к этому исключительно кошмарному виду чумы.', '', '\"Взбодренный\" Марилетом образец чумы. Он оказался куда злее, чем ожидалось.', '', '', '', '', 45114),
(65664, 'ruRU', 'Сущность чумы', 'Попробуйте разные зелья в доме Чумы.', 'Вижу, твой дружок проголодался! Не волнуйся, у меня как раз найдется подходящий корм. Скоро он вырастет большим и сильным, и тогда сможет есть любую чуму без разбора.\n\nЗдесь есть зелья, которые усилят его способности. И у каждого цвета свой вкус!\n\nЯ отнесу образец чумы подальше и попробую его изучить. Найди меня там, когда твой пожиратель чумы отобедает по первому разряду.', '', '', '', '', '', 'Встретьтесь с изобретателем чумы Марилетом в глубине дома Чумы.', 45114),
(65663, 'ruRU', 'Пища для пожирателя', 'Убивайте слизнюков и чумных рухов в доме Чумы.', 'Дом Чумы постигла катастрофа, как и Лордерон. Будем надеяться, наш труд хоть немного исправит причиненный вред.\n\nНо сначала надо зайти подальше в дом Чумы, чтобы пожиратель чумы Фаранелла набрался сил.\n\nУбитые слизнюки или другие существа должны укрепить его.', '', '', '', '', '', 'Встретьтесь с Калией Менетил в глубине дома Чумы.', 45114),
(65662, 'ruRU', 'Дом Чумы', 'Встретьтесь с изобретателем чумы Марилетом в доме Чумы.', 'На твои вопросы ответит один из выживших дома Чумы. Ты уже его знаешь.\n\nЯсность ума – не самая сильная сторона изобретателя чумы Марилета, но он расскажет тебе все про эту чуму.\n\nПоищи его около руин его павшего дома. Только осторожно! Многие его обитатели прикончат тебя без всякой жалости.', '', '', '', '', '', 'Встретьтесь с изобретателем чумы Марилетом в доме Чумы.', 45114),
(65661, 'ruRU', 'Мудрость союзников', 'Поговорите с маркграфиней Син\'дейн в Малдраксусе.', 'Надеюсь, Калия не ошиблась насчет этих правителей Малдраксуса. И насчет их умения обращаться с такой ядовитой чумой.\n\nК тому же у нас остался всего один пожиратель чумы, но Фаранелл говорит, что разведет еще, если чума их не убьет.\n\nЧто ж, пора в Темные Земли.', '', '', '', '', '', 'Поговорите с маркграфиней Син\'дейн в Малдраксусе.', 45114),
(65660, 'ruRU', 'Тропа веры', 'Защитите Калию за ее щитом и соберите образцы чистой чумы.', 'Я обещала помочь и держу слово. Нам нужен чистый образец лордеронской чумы, но посылать кого-то за ним было бы слишком опасно.\n\nИди за мной. Я создам барьер Света, который оградит нас от чумы и позволит без риска забрать образец.\n\nЗаклинание требует полной сосредоточенности. Тебя я прошу защищать нас от любых попыток помешать мне.\n\nНу что, пошли?', '', '', '', '', '', 'Вернитесь к Лилиан Восс около Брилла.', 45114),
(65659, 'ruRU', 'Переговоры о чуме', 'Выслушайте Отрекшихся.', 'На долю Отрекшихся выпало много испытаний со времен разрушения Лордерона. Но мы твердо намерены сберечь свой дом.\n\nЗачем нам бросать то, за что так долго боролись?\n\nКалия среди нас относительно недавно, но мы все ее очень хорошо знаем. Как не знать сестру самого Артаса?\n\nЯ надеюсь на успех нашей затеи и на ее помощь в том числе. Она сыграет важную роль, если в самом деле решит присоединить свой голос к нашим.', '', '', '', '', '', 'Встретьтесь с Калией Менетил возле Брилла.', 45114),
(65658, 'ruRU', 'Эта земля принадлежит нам', 'Убейте чумных солдат в Тирисфальских лесах.', 'Чума Четвертой войны заразила землю и растревожила мертвых. То есть сильнее, чем обычно.\n\nМы стараемся восстановить город как можем, но эта угроза мешает закончить работу.\n\nМой первейший долг – позаботиться о безопасности Отрекшихся. Я выполню просьбу Калии и встречусь с остальными, но сначала помоги мне избавиться от зачумленных.', '', '', '', '', '', 'Встретьтесь с темным следопытом Велонарой в таверне Брилла.', 45114),
(65657, 'ruRU', 'Сбор Отрекшихся', 'Пригласите на встречу темного следопыта Велонару, Лилиан Восс и мастера-аптекаря Фаранелла.', 'Успехи в восстановлении Брилла воодушевляют, но это только первый шаг. К руинам столицы невозможно приблизиться из-за чумы.\n\nИ здесь я надеюсь на твою помощь.\n\nЧтобы исцелить эти земли, мы должны найти решение все вместе.\n\nНесколько известных Отрекшихся пользуются особенным уважением. Организуй их встречу, чтобы мы смогли обсудить наши дальнейшие шаги.', '', '', '', '', '', 'Встретьтесь с Лилиан Восс в таверне Брилла.', 45114),
(65656, 'ruRU', 'Призыв в Лордерон', 'Встретьтесь с Калией Менетил в Брилле в Тирисфальских лесах.', 'Темные Земли вновь процветают, и пришла пора направить усилия на наш родной Азерот.\n\nОтрекшиеся собираются в руинах королевства Лордерон. Они хотят по мере сил вернуть себе Тирисфальские леса, чтобы наконец избавиться от страшного наследия Четвертой войны.\n\nА я собираюсь их поддержать в этом.\n\nЯ знаю, что мне нужно многое доказать и перед Ордой. Присоединяйся ко мне в Брилле, и вместе мы поможем там Отрекшимся.', '', '', '', '', '', 'Встретьтесь с Калией Менетил в Брилле в Тирисфальских лесах.', 45114),
(65653, 'ruRU', 'Слава син\'дорай', 'Вернитесь к леди Лиадрин в Луносвет.', 'Протазан истратил всю свою силу, но победа за нами! Без Вората с Плетью будет гораздо проще разобраться – благодаря тебе.\n\nНайди меня в Зале Крови. Луносвет благодарит тебя за отвагу.', '', '', '', '', '', '', 45114),
(65652, 'ruRU', 'Призыв матриарха', 'Встретьтесь с леди Лиадрин в Луносвете.', 'Здравствуй, $n.\n\nПерейдем сразу к делу – ты срочно $gнужен:нужна; в Луносвете. \n\nНа Кель\'Талас надвигается новая волна Плети. Если не принять меры, она сметет наши силы сопротивления. Мы должны сдержать врага!\n\nНайди меня в Зале Крови, чтобы обсудить детали.', '', '', '', '', '', 'Встретьтесь с леди Лиадрин в Луносвете.', 45114),
(65649, 'ruRU', 'Новая сделка', 'Соберите $1oa |4нить:нити:нитей; протоплазмы в Зерет Мортисе в режиме войны.', 'А! Пилигрим Утробы! Тебе удалось найти дорогу в Зерет Мортис, а это открывает колоссальные возможности. \n\nУ меня к тебе новое дело. Обсудим?\n\nНам бы хотелось оценить потенциал нового пути. Не сомневаюсь, ты сможешь добыть то, что нам нужно. И не позволяй никому переходить тебе дорогу!\n\nНо если не захочешь, то я найду кого-нибудь еще, кто решит обе наши проблемы.', '', '', '', '', '', '', 45114),
(65563, 'ruRU', 'Посылка для Кейси', 'Отнесите клинковый шлем Кейси Кузне Гнева.', 'Я изготовил кое-что для Кейси из твоих материалов. Надеюсь, ты не против.\n\nОтнесешь ей этот шлем?', '', '', '', '', '', '', 45114),
(65463, 'ruRU', 'Родник Предвечных', 'Поговорите с охранителем Олемом о проблеме с родником.', 'Смертная душа? Здесь? Как неожиданно! Приветствую тебя в Приюте Пилигрима. Жаль, что ты $gоказался:оказалась; здесь при таких обстоятельствах. Обычно пилигримы приходят сюда ради священного родника Предвечных. \n\nБоюсь, он полностью иссяк. Я не понимаю, как это произошло. Творения Предвечных всегда были безупречны! \n\nЭта ситуация так же необычна, как твое прибытие. Быть может, ты нам и поможешь? Иди к роднику и поговори с охранителем Олемом.', '', '', '', '', '', '', 45114),
(65448, 'ruRU', 'Возвращение в Приют', 'Сообщите охранителю Олему хорошие новости.', '<Защита храма восстановлена, а нанесенный ему ущерб устранен. Теперь родник в безопасности. Охранитель Олем будет рад новостям о вашем успехе.>', '', '', '', '', '', 'Вернитесь к Олему.', 45114),
(65445, 'ruRU', 'Подготовка ресурсов', 'Добудьте $1oa ед. осадка неочастиц и $2oa |4отвердевшую неочастицу:отвердевшие неочастицы:отвердевших неочастиц; у пожирателей в Зерет Мортисе.', 'Пожиратели поглощают неочастицы.\n\nОни нам нужны для новых творений. Без них мы не сможем завершить работу.\n\nУничтожь пожирателей и верни неочастицы.', '', '', '', '', '', '', 45114),
(65433, 'ruRU', 'Дальнейшие исследования: требелимский', 'Продолжите изучать шифровальную консоль в пещере Изгнанника.', '<Консоль слабо гудит, излучая таинственную энергию.>', '', '', '', '', '', '', 45114),
(65427, 'ruRU', 'Новый архитектор', 'Добудьте $1oa |4матрицу сервида:матрицы сервида:матриц сервида; и $2oa |4инструмент протосинтеза:инструмента протосинтеза:инструментов протосинтеза; и принесите их к интерфейсу сервитора в Проторепозитории.', 'Архитекторы создают первоначальные чертежи, служащие целям Предвечных. \n\nРаньше в данном архиве хранилось множество таких чертежей.\n\nВ ходе нашествия Верных Утробе многие чертежи были потеряны или испорчены. \n\nНедалеко отсюда обнаружена нетронутая матрица чертежа и нужные инструменты. $gСмертный должен:Смертная должна; забрать их и запустить процесс синтеза.', '', '', '', '', '', '', 45114),
(65426, 'ruRU', 'Утраченный компонент', 'Возьмите катализатор протосинтеза и верните его в Проторепозиторий.', 'Пилигрим! Смотри!\n\nМы уже давно изучаем эту деталь автома. Изображенные на ней шифры очень похожи на шифры автомов возле Проторепозитория и в нем самом.\n\nСтарания Кодаха не должны пропасть зря. Верни эту деталь в репозиторий, который удалось восстановить благодаря нашему другу.', '', '', '', '', '', 'Обратитесь к интерфейсу сервитора в Проторепозитории.', 45114),
(65420, 'ruRU', 'Зов правосудия', 'Поговорите со старейшиной Амиром в Приюте Пилигрима.', 'О, нет... Нет-нет-нет... Что я наделала?\n\nСтарейшины никогда не примут меня обратно. Меня прогонят, как Фирима.\n\nТебе, $gчужеземцу:чужеземке;, нечего бояться. Прошу, поговори со старейшиной Амиром в Приюте Пилигрима. Передай ему мою благодарность за то, что он прислал тебя, и расскажи обо всем, что случилось. Он поймет, почему мне нельзя вернуться.', '', '', '', '', '', 'Поговорите со старейшиной Амиром в Приюте Пилигрима.', 45114),
(65419, 'ruRU', 'Протосинтез', 'Сопроводите Покопока к кузне протосинтеза.', '<Покопок подскакивает от нетерпения. Видя, что вы освоили основы деалического, он воодушевляется и манит вас за собой в другую точку этого царства.>', '', '', '', '', '', '', 45114),
(65412, 'ruRU', 'Разрешить загадку', '', '', '', '', '', '', '', '', 45114),
(65411, 'ruRU', 'Запутанная ситуация', '', '', '', '', '', '', '', '', 45114),
(65370, 'ruRU', 'Проверка нутра', 'Добудьте крещендал у алчущего крушителя или ненасытного ловчего на Террасе Формирования.', 'Крещендалы – это мощные инструменты, созданные автомами. Джиро получают их, когда выполняют сложную или важную работу. Когда на нас напали пожиратели, они скорее всего... съели крещендалы.\n\nЭто очень крепкие инструменты. Их нелегко повредить. Поищи в желудках крупных пожирателей. Возможно, найдется целый крещендал?', '', '', '', '', '', '', 45114),
(65364, 'ruRU', 'Супер-джирой', 'Управляя джиро Прайм, спасите $4oa |4паникующего джиро:паникующих джиро:паникующих джиро;, а также убейте $2oa |4сломленного Утробой автома:сломленных Утробой автомов:сломленных Утробой автомов; и $3oa |4Верного Утробе:Верных Утробе:Верных Утробе;.', 'Враждебные чужаки мешают джиро выполнять задания и следовать предназначению. Это не должно продолжаться.\n\nЧтобы разобраться с напастью, мы усилим большого джиро. Джиро Прайм уничтожит врагов, посягающих на Зерет Мортис.\n\nНаправь его на противника, чтобы избавиться от угрозы.', '', '', '', '', '', '', 45114),
(65362, 'ruRU', 'Чужие среди чужих', 'Убейте $1oa |4повелителя ужаса - лазутчика:повелителей ужаса - лазутчиков:повелителей ужаса - лазутчиков;.', 'Некоторые враги Зерет Мортиса притворяются трудящимися автомами. На самом деле они не делают ничего полезного.\n\nПросканируй автомов, и если обнаружишь врагов, избавься от них.\n\nМаи Обет тебе поможет.', '', '', '', '', '', '', 45114),
(65353, 'ruRU', 'Безавтомовая диета', 'Убейте $1oa |4атакующего поглотителя:атакующих поглотителей:атакующих поглотителей; или |4разрушителя реальности:разрушителей реальности:разрушителей реальности;.', 'Этих пожирателей ничто не останавливает! Они пожирают любые источники энергии. Если их не остановить, они поглотят весь Зерет Мортис. Нельзя допустить, чтобы эти твари оскверняли творения Предвечных! \n\nИз меня боец никудышный, но ты... Возможно, Предвечные действительно послали тебя к нам. Ты поможешь?', '', '', '', '', '', 'Вернитесь к Надиру.', 45114),
(65350, 'ruRU', 'Восстановить поток', 'Найдите способ восстановить локрийский эспер.', 'Смотри! Пожиратели пробились через защиту храма. Эти ненасытные чудища постоянно пытаются поживиться энергией. Должно быть, их привлекла сюда сила родника.\n\nНеудивительно, что поток воды остановился!\n\nДумаю, суть проблемы кроется в локрийском эспере. Когда окажешься там, постарайся устранить ущерб, нанесенный пожирателями.', '', '', '', '', '', '', 45114),
(65349, 'ruRU', 'Потеря Приюта', 'Отправляйтесь в провиз эсперов.', 'Вода из священного родника совсем иссякла.\n\nТворения Предвечных раньше никогда нас не подводили. Многие пилигримы начинают беспокоиться... вдруг мы чем-то разозлили Предвечных?\n\nПредаваться сомнениям совершенно естественно, но я продолжаю верить. И не напрасно – Предвечные уже послали нам решение. \n\nТебя, конечно же. \n\nСогласно древним текстам, источник родника находится в подземном храме провиза эсперов. Отправляйся в путь. Я верю, что ты вернешь нам воду.', '', '', '', '', '', 'Обыщите поврежденного локрийского техника.', 45114),
(65335, 'ruRU', 'Новости из Орибоса', 'Поговорите с Утером Светоносным.', 'Я пришел передать тебе кое-что важное. Эти знания позволят нам лучше понять силу Тюремщика. \n\nСохранив веру и понимание, мы сможем добиться истинного правосудия.\n\nНам нужно многое обсудить, герой.', '', '', '', '', '', '', 45114),
(65331, 'ruRU', 'Целебные травы', 'Уничтожьте $1oa |4разумную поросль:разумные поросли:разумных порослей; и $2oa |4хищную поросль:хищные поросли:хищных порослей;.', 'Из собранных тобой корней мне удалось изготовить целебный отвар. Если мои догадки верны, он вернет растения в обычное состояние.\n\nПопробуй забросать плеточников в Садах Катализации флаконами с противоядием.\n\nЕсли оно сработает – замечательно! Если нет, то тебе придется разобраться с проблемой напрямую. Истребив растения.', '', '', '', '', '', '', 45114),
(65329, 'ruRU', 'Безопасное укрытие', 'Вернитесь к Болвару в Укрытие.', 'Вернемся в Зерет Мортис. Как только окажешься там, сообщи Болвару о нашем успехе. Это значимая победа, но нам предстоит еще многое сделать.', '', '', '', '', '', 'Вернитесь к Болвару в Укрытие.', 45114),
(65328, 'ruRU', 'Будущий Арбитр', 'Отправляйтесь в Укрытие и сообщите, что Саезура хочет создать нового Арбитра.', 'Пилигрим, я... не знаю, что и сказать. Это так неожиданно.\n\nОна говорила о приготовлениях. О создании нового Арбитра. Надо рассказать нашим друзьям в Укрытии.', '', '', '', '', '', 'Сообщи эту новость Болвару в Укрытии.', 45114),
(65326, 'ruRU', 'Цикл раздора', 'Осмотрите $1oa |4автома-конструктора:автомов-конструкторов:автомов-конструкторов; в провизе флоры.', 'Чтобы автомы работали исправно, им нужно обслуживание. Этим занимаемся мы, но с прибытием чужаков у нас появилось много других проблем. Теперь мы не можем уделить внимание всем автомам. \n\nПожалуйста, помоги Маи Обет осмотреть автомов и оценить их состояние.', '', '', '', '', '', '', 45114),
(65325, 'ruRU', 'Частицы знания', 'Верните $1oa |4компилирующий блок:компилирующих блока:компилирующих блоков; и $2oa |4частицу композиции:частицы композиции:частиц композиции;.', 'Существа в Неукротимых зарослях жрут все, до чего доберутся. Они уже поглотили наш компилирующий блок и частицы композиции, необходимые при компиляции. Эти ресурсы нам нужны.\n\nТут слишком опасно. Мы не можем находиться здесь без защиты.\n\nПомоги нам вернуть ресурсы. Маи Обет тебе поможет.', '', '', '', '', '', '', 45114),
(65297, 'ruRU', 'Покаяние и возрождение', 'Поговорите с Тирандой в Кольце Перенаправления в Орибосе.', 'Став новым Арбитром, я дал себе клятву, что перед вынесением вечного приговора буду прислушиваться к советам окружающих.\n\nДумаю, я уже догадываюсь, какую участь Тиранда выбрала бы для Сильваны. Ее гнев уравновешен мудростью. Я верю, что ее решение будет справедливым.\n\nВстреться с ней в Кольце Перенаправления и проследи за исполнением ее приговора.', '', '', '', '', '', '', 45114),
(65269, 'ruRU', 'Обычное растение', 'Разместите сенсоры магии Прародителей в Садах Катализации.', 'Меня очень беспокоит обстановка в Садах Катализации.\n\nИ самое худшее, мы не понимаем, что именно там происходит. Если мы проследим, как изменяется объем энергии, выделяемой Катализатором творения, то сможем понять, как исправить ситуацию.\n\nВозьми эти сенсоры. Размести их под Катализатором в местах, которые я отмечу на твоей карте.', '', '', '', '', '', '', 45114),
(65268, 'ruRU', 'Бзз-з!', 'Извлеките осколки реликвий Прародителей из гнезд веспоидов с помощью устройства Просветленного брокера.', 'Местные веспоиды строят гнезда из мусора и обломков. Это совершенно естественно, и обычно мы стараемся им не мешать, но в последнее время они начали забирать реликвии, которые мы изучаем.\n\nЯ подготовил устройство, которое должно извлечь реликвию из гнезда, не нарушив его целостность. Возьми его и верни реликвии.', '', '', '', '', '', '', 45114),
(65265, 'ruRU', 'Закопанные останки', 'Добудьте странные артефакты из провиза страты.', 'Захватчиков заботит лишь война и разрушения. Мы уже многое из-за них потеряли.\n\nМы не сможем сохранить это царство таким, каким его задумали Предвечные, если позволим Верным Утробе обратить в прах все их знания.\n\nПостарайся спасти хоть что-то из песков провиза страты.', '', '', '', '', '', '', 45114),
(65264, 'ruRU', 'Операция \"Релокация\"', 'Доставьте $2oa |4пойманного дикого протоавиана:пойманных диких протоавианов:пойманных диких протоавианов; и убейте $3oa |4жаждущего душ поглотителя:жаждущих душ поглотителей:жаждущих душ поглотителей; и $4oa |4разрушителя реальности:разрушителей реальности:разрушителей реальности; в провизе эсперов.', 'Пожиратели добрались до гнезд авианов в провизе эсперов.\n\nВозможно, это наш последний шанс изучить этих существ прежде, чем их тоже поразит порча.\n\nПоймай несколько авианов и доставь пилигриму Арижу. Он подберет им новое жилье и займется их изучением. Если возникнут помехи, ты знаешь, как с ними разобраться.', '', '', '', '', '', '', 45114),
(65263, 'ruRU', 'Судьба Сильваны', 'Поговорите с Пелагием, чтобы выслушать приговор Сильваны Ветрокрылой.', 'Время пришло.\n\nСегодня мрачная история Сильваны Ветрокрылой закончится, а над Темными Землями взойдет новый рассвет.\n\nСкажи, когда будешь $gготов:готова;, и мы начнем суд.', '', '', '', '', '', '', 45114),
(65260, 'ruRU', 'Долгое путешествие', 'Поговорите с Утером в Орибосе, чтобы сопроводить Сильвану в Анклав, а затем поговорите с Тал-Инарой, чтобы перенестись в Горнило.', 'Арбитр ждет нас. Обычно в Горнило пускают только избранных, но некоторым выходцам из Азерота разрешили присутствовать при вынесении приговора.\n\nИ Сильвана принесла смерть и разрушения не только нам. От ее действий пострадали многие.\n\nИ выкрикнуть оскорбление ей вслед – для кого-то единственная возможность высказаться. Так пусть они будут услышаны.', '', '', '', '', '', 'Встретьтесь с Пелагием в Горниле Орибоса.', 45114),
(65259, 'ruRU', 'Сердце Гробницы', 'Победите Тюремщика в Гробнице Предвечных.', 'Вскоре после того, как мы оказались в царствах Смерти, нам раскрылось послание Примаса с наказом не пускать Тюремщика в Гробницу.\n\nНо наших усилий оказалось недостаточно, и он туда проник.\n\nВ сердце этой древней святыни хранятся тайны, которые позволят ему поработить все мироздание. Если его замысел свершится, все, чем мы дорожим, будет потеряно.\n\nСобери союзников, $n. Одолей врага ради Темных Земель... и Азерота.', '', 'Замысел Тюремщика не должен свершиться. Судьба всего сущего – в ваших руках. Остановите его.', 'Зоваал', '', '', '', 45114),
(65255, 'ruRU', 'Форсирование цикла', 'Зарядите и очистите сферу Прародителей.', 'Силы Зоваала оказывают пагубное влияние на живую природу провиза фауны. Порча распространяется так быстро, что попытки очистить каждое животное просто не помогут.\n\nВместо этого мы можем вернуть их энергию во внутренние механизмы Зерет Мортиса, чтобы из нее получились новые звери. Позволь этой сфере поглотить энергию умирающих зверей, а затем очисти ее, когда сфера будет полностью заряжена.', '', '', '', '', '', '', 45114),
(65252, 'ruRU', 'Раздави это!', '', '', '', '', '', '', '', '', 45114),
(65250, 'ruRU', 'Главный узник', 'Поговорите с Утером в Орибосе и сопроводите Сильвану к Арбитру.', 'Тюремщик побежден, и теперь мы должны заняться исцелением ран, которые он нанес Темным Землям. Начнем с Сильваны Ветрокрылой.\n\nХотя ее содействие было незаменимым для нашей победы, ужасные преступления нельзя ни простить, ни забыть. Ее будет судить новый Арбитр Орибоса.\n\nУтер ждет тебя в Кольце Судеб. Вместе вы сопроводите Сильвану в Горнило.', '', '', '', '', '', 'Поговорите с Утером в Орибосе.', 45114),
(65249, 'ruRU', 'Победа над Тюремщиком', 'Поговорите с Болваром, чтобы вновь увидеть победу над Тюремщиком.', 'После стольких усилий мы наконец-то сорвали замысел Тюремщика. \n\nКузня Посмертий и душа Азерота восстановлены, а Темные Земли начинают исцеляться после засухи анимы.\n\nЯ понимаю, что ты $gпривык:привыкла; всегда двигаться вперед. Но мы одержали великую победу, а над этим стоит поразмыслить.', '', '', '', '', '', '', 45114),
(65245, 'ruRU', 'Избавление от пожирателей', 'Убейте мутировавших пожирателей на Пиках Отголосков.', 'Когда-то... у них была цель. Они восстанавливали равновесие. Но они... изменились. Они нарушают гармонию.\n\nИскажают схему. Это продолжаться не может.\n\nУничтожение – единственный выход.', '', '', '', '', '', '', 45114),
(65244, 'ruRU', 'К пожиранию пригодно', '', '', '', '', '', '', '', '', 45114),
(65238, 'ruRU', 'Взаимосвязь душ', 'Поговорите с Тал-Инарой в Орибосе.', 'Надо признать, поначалу мне показалось, что Пелагий идет на огромную жертву. Но теперь я вижу – он просто делился с Темными Землями своей надеждой и состраданием. Нам нужно с ним встретиться.\n\nПоговори с Тал-Инарой, когда доберешься до Орибоса.\n\nСкоро я тоже туда прибуду.', '', '', '', '', '', '', 45114),
(65237, 'ruRU', 'Оракул, исцели себя сам', 'Приведите Покопока к Саезуре.', 'Сосуд был спасен от угрозы. Этот автом верно служил мне. Его энергия меня восстановит.\n\nОн зовет себя Покопок. Скоро он вновь обретет свое имя.\n\nА мое имя вернется ко мне. Саезура, одна из последних оракулов. Проводница тех, кто спасет Зерет Мортис.\n\nПриведи сюда Покопока. Больше он не будет посредником. Пришло время мне пробудиться.', '', '', '', '', '', 'Поговорите с Саезурой.', 45114),
(65231, 'ruRU', 'Украденное знание', '', '', '', '', '', '', '', '', 45114),
(65226, 'ruRU', 'Быстроног и привередлив', 'Помогите Ране вернуть $3oa |4украденную реликвию:украденные реликвии:украденных реликвий; и убейте $4oa |4вороватую крысу:вороватых крыс:вороватых крыс; Утробы.', 'Когда Верные Утробе ворвались в Зерет Мортис, за ними увязались крысы Утробы! \n\nИх стая прошмыгнула в мою пещеру и утащила кучу предметов, необходимых для исследований!\n\nРана вызвалась собрать команду для поиска пропавших вещей. Найди ее и помоги в поисках.', '', '', '', '', '', '', 45114),
(65219, 'ruRU', 'Джиро – герой!', 'Защищайте джиро от пожирателей, пока они устанавливают подавляющее поле.', 'Я говорила с другими джиро. Наша сфера может образовать подавляющее поле. Оно закроет разломы и предотвратит появление новых.\n\nЭто надо сделать там, где магия Утробы особенно сильна. Между огромными цепями. Высвобожденная сила привлечет пожирателей. Нам с тобой нужно будет защищать сферу, пока не появится поле.\n\nЯ приведу остальных. Приходи к разлому, когда будешь $gготов:готова;.', '', '', '', '', '', 'Поговорите с Ханоа Изгнанницей у Края Зоваала.', 45114),
(65143, 'ruRU', 'Антрос', '', '', '', '', '', '', '', '', 45114),
(65119, 'ruRU', 'Автовойска', '', '', '', '', '', '', '', '', 45114),
(65117, 'ruRU', 'Неудачные образцы', '', '', '', '', '', '', '', '', 45114),
(65115, 'ruRU', 'В поисках решения', '', '', '', '', '', '', '', '', 45114),
(65096, 'ruRU', 'Выживет лишь один', 'Убейте карателя Макариса и добудьте $2oa |4священную реликвию:священные реликвии:священных реликвий;.', 'Изучив реликвии из Извечных Осколков, мы почерпнули уйму ценной информации. \n\nУвы, Верные Утробе прознали о наших находках и теперь хотят нам помешать. Они разместили ловушки вокруг найденных реликвий, чтобы мы не могли до них добраться. \n\nМы должны сохранить к ним доступ несмотря ни на что.\n\nПожалуйста, избавься от Верных Утробе и добудь как можно больше реликвий.', '', 'Создатель многих ловушек Торгаста. Теперь он размещает их и в Зерет Мортисе.', 'Каратель Макарис', '', '', '', 45114),
(65081, 'ruRU', 'По яблоку в день', '', '', '', '', '', '', '', '', 45114),
(64977, 'ruRU', 'Шаг в круг', 'Победите созданных существ в Нексусе Воплощения.', 'Одним из примечательных свойств этого царства оказалось то, что оно хоть и древнее, вполне может адаптироваться к изменениям. Здесь ничто не стоит на месте.\n\nВ глубине Нексуса Воплощения находится кузня. Кажется, она проверяет новые проекты и анализирует результаты. Возможно, однажды полученные существа смогут встать на защиту Зерет Мортиса, так что постарайся проверить, насколько они сильны.\n\nИди к кузне, сразись с существами, которых она создаст, и сообщи мне о результатах.', '', '', '', '', '', '', 45114),
(64969, 'ruRU', 'Среди трав', 'Встретьтесь со старейшиной Арой у входа во Двор Катализатора.', 'Теперь я понимаю, из-за чего старейшина Нирав так беспокоится.\n\nМногие пилигримы, отправившиеся во Двор Катализатора, до сих пор не вернулись. Среди них был и Фероз. Он вероятнее других знает, как восстановить обломки. \n\nХорошенько приготовься. Вокруг Катализатора обитают самые последние творения Предвечных. Если там что-то пошло не так, последствия могут быть поистине ужасными.', '', '', '', '', '', '', 45114),
(64964, 'ruRU', 'Выбор бойца', 'Выберите автома и направьте его против Верных Утробе.', 'Силы Тюремщика наносят провизу страты невообразимый ущерб. Если их не остановить, мы потеряем все хранящиеся там знания.\n\nОдин из наших собратьев подготовил несколько автомов для борьбы с Верными Утробе. Найди их и одолей всех, кто посмел осквернить земли Зерет Мортиса.', '', '', '', '', '', '', 45114),
(64962, 'ruRU', 'Как и было предсказано', 'Отведите Фирима и провидцев в центр.', 'Все сферы на своих местах. Я слышу мелодию. Давай же, возглавь хор провидцев. Начни цикл перерождения.', '', '', '', '', '', '', 45114),
(64960, 'ruRU', 'Подкормка аннелидов', '', '', '', '', '', '', '', '', 45114),
(64937, 'ruRU', 'Ты делаешь мою жизнь ярче', 'Используйте Покопока, чтобы защитить сосуд от пожирателей.', 'Великая сила привлекает великий голод. Ненасытные пожиратели лезут на скалы в поисках пищи.\n\nСкоро здесь будет целое полчище. Они поглотят все на своем пути. Сосуд. Его силу. Нас с тобой.\n\nЭтого не должно случиться. Используй этого автома. Прерви их алчущий вой.', '', '', '', '', '', 'Доставьте сосуд Фириму в пещеру Изгнанника.', 45114),
(64936, 'ruRU', 'Тщательные поиски', 'Добудьте слова доступа в финальной конфигурации Локуса, необходимые, чтобы получить сосуд.', 'Три замка на двери, три ключа на вершине.\n\nНайди нужные слова. Произнеси их. Доберись до сосуда.', '', '', '', '', '', 'Поговорите с Покопоком у пустого сосуда.', 45114),
(64935, 'ruRU', 'Меж двух камней', 'Разбейте обломки, преграждающие путь ко второй конфигурации Локуса.', '<Земля вокруг усеяна грудами камней. Пожиратели разгромили это место, скрыв шифр за обломками.\n\nВозможно, один из местных сервиторов сможет разобрать завалы.>', '', '', '', '', '', '', 45114),
(64889, 'ruRU', 'Соединенные Зерет Мортисом', 'Изучите конфигурации Локуса и доберитесь к финальной конфигурации с помощью \"Сдвига Локуса\".', 'Шифры – ключ ко всему. Каждый из них – новый шаг на пути. Найди их все.\n\nВойди во внутренний зал. Там ждет первая конфигурация Локуса.\n\nПервая ступень к вознесению. К новому сосуду.', '', '', '', '', '', '', 45114),
(64888, 'ruRU', 'Сила взаймы', 'Убивайте привлеченных нестабильных противников или поглощайте силу из особых областей, чтобы зарядить Покопока космической энергией.', 'Природа одаривает. Природа жаждет. Чужаки пожирают то, что нам нужно.\n\nВерни то, что они поглотили. Собери то, что сохранилось в изобилии.\n\nЧтобы летать, крыльям нужен ветер. Чтобы вознестись, нам нужна сила.', '', '', '', '', '', '', 45114),
(64879, 'ruRU', 'Монументальное открытие', 'Встретьтесь с Фиримом в пещере Изгнанника.', 'Пилигрим... недавно Пелагий докладывал мне обстановку и передал, что оракул закончила приготовления и ждет твоего возвращения. \n\nЕсли это как-то связано с нашей общей целью, я советую тебе немедленно отправиться к ней. Поспеши в пещеру Изгнанника и узнай, что от тебя требуется.', '', '', '', '', '', '', 45114),
(64878, 'ruRU', 'Долгое странное путешествие', 'Следуйте за Покопоком, чтобы понять суть вашего видения.', '<Из Покопока раздается голос, который вы слышали в видении. В этот раз он кажется отдаленным и искаженным.>\n\nМеня зовут... Саезура. Я оракул. Этот автом... говорит моим голосом. Действует по моей воле. Временно.\n\nСхема... была испорчена. Нарушена. Ее нужно исправить.\n\nВ песках объявилась голодная сущность. Она не должна поглотить то, что ищет.\n\nОтправимся в путь. Следуй за моим голосом.', '', '', '', '', '', 'Найдите Покопока в месте вашего видения.', 45114),
(64876, 'ruRU', 'Музыка сфер', 'Осмотрите фракталы, окружающие Саезуру.', 'Все происходило постепенно: сперва оракул начала излучать энергию. Ее становилось все больше и больше, пока не явилась великая схема, что и сейчас перед нами.\n\nА этот ужасный звон в ушах появился немного позже.\n\nЛюбая попытка приблизиться к фракталам завершалась для меня... довольно прискорбно. Но, кажется, они вошли в резонанс с Покопоком.\n\nУ вас с ним особая связь, а значит, тебе может повезти больше, чем мне.', '', '', '', '', '', '', 45114),
(64875, 'ruRU', 'Нечто чудесное', 'Отправляйтесь в пещеру Изгнанника и посмотрите, что происходит с Саезурой.', '$n! Как хорошо, что ты здесь! Фирим просил тебя найти.\n\nДело в оракуле... Она... Не знаю, как объяснить. Лучше идем, и ты $gсам:сама; все увидишь. Скорее!', '', '', '', '', '', 'Отправляйтесь в пещеру Изгнанника и поговорите с Фиримом.', 45114),
(64870, 'ruRU', 'Идеал Просветленных брокеров', 'Поговорите с Вило в Укрытии в Зерет Мортисе.', 'Ну и ну. Я вижу, ты не $gтерял:теряла; времени даром.', '', '', '', '', '', '', 45114),
(64854, 'ruRU', 'В погоне за успехом', 'Убейте $1oa |4Верного Утробе криптопровидца:Верных Утробе криптопровидцев:Верных Утробе криптопровидцев; и изучите перечисленных животных.', 'Животных Зерет Мортиса привлекают бурные потоки энергии творения, протекающие через это царство. И когда они находят что-то, заряженное этой энергией... они сразу это съедают!\n\nВерные Утробе криптопровидцы это заметили и теперь охотятся на животных, из которых можно извлечь остатки энергии.\n\nИзбавься от криптопровидцев, а также используй сдерживающую ловушку, чтобы изучить местную фауну.', '', '', '', '', '', '', 45114),
(64853, 'ruRU', 'Два пути', 'Явитесь с докладом к Примасу в Геометрическую пещеру.', 'Ты $gполучил:получила; ответ на свой вопрос?\n\nА, тебе хотелось узнать, как полностью защититься от магии Господства? Этого, боюсь, я не знаю. Язык Предвечных лишь оттягивает неизбежное.\n\nНо если тебе понадобятся новые упоительно сложные фразы на языке Предвечных, иди в Бесконечные пески и обыщи склепы.\n\nМне бы и самой хотелось туда сходить, но склепы кишат этими гадкими Верными Утробе.\n\nУдачи тебе в учебе!', '', '', '', '', '', 'Явитесь с докладом к Примасу в Геометрическую пещеру.', 45114),
(64844, 'ruRU', 'Конец похода', 'Вернитесь на смотровую площадку за Приютом Пилигрима.', 'Ты $gспас:спасла; многих пилигримов, а я помогла открыть путь в Гробницу. На этом обе части сделки выполнены... а мое паломничество подходит к концу.\n\nНо твой путь еще не закончен.\n\nВернись на смотровую площадку за Приютом Пилигрима и открой транслокатор.\n\nСпасибо тебе, $n. Наше путешествие оказалось... крайне познавательным.', '', '', '', '', '', '', 45114),
(64843, 'ruRU', 'Создание ключа', 'Восстановите ключ транслокации в Катализаторе творения.', 'С разъяренными автомами разобрались, теперь дело за малым.\n\nМы доставим тебя и твою Просветленную спутницу к Катализатору творения.\n\nДальше вы сами.', '', '', '', '', '', '', 45114),
(64842, 'ruRU', 'Бурный рост', 'Выпейте отвар Фероза и уничтожьте автомов в Садах Катализации.', 'Те автомы-стражи сбивают каждого, кто приближается к Катализатору творения.\n\nПредлагаю решение по принципу \"Огонь против огня\". В данном случае – энергия Предвечных против творений Предвечных.\n\nЯ не успел проверить свои догадки, но это зелье должно придать тебе достаточное ускорение, чтобы уничтожить помеху... А если все пройдет совсем гладко, ты не получишь смертельную дозу энергии творения.', '', '', '', '', '', '', 45114),
(64841, 'ruRU', 'Зарядка', 'Выпустите избыточную энергию Катализатора творения.', 'Та башня, что парит над нами – это Катализатор творения.\n\nУвы, я не могу к нему подобраться. Катализатор переполнен энергией Прародителей. Приблизиться к нему сейчас было бы самоубийством.\n\nВ садах есть консоли, позволяющие убавить уровень энергии. Сделаешь это?', '', '', '', '', '', '', 45114),
(64840, 'ruRU', 'Запущенная поросль', 'Добудьте $1oa |4порцию:порции:порций; растущей сущности.', 'Эта энергия роста очень необычная. Я хочу посмотреть, как она влияет на здешних автомов.\n\nСобери растущую сущность у погибших автомов в Садах Катализации.\n\nПринеси ее, чтобы я смог ее изучить.', '', '', '', '', '', '', 45114),
(64839, 'ruRU', 'Корень проблемы', 'Соберите заряженные растительные волокна.', 'Я подозреваю, что мы можем использовать энергию роста, собранную у местных растений. Чтобы в этом убедиться, мне нужны свежие образцы.\n\nЗаряженные растительные волокна можно добыть у плеточников или обвитых лианами автомов, которые обитают здесь и во Дворе Катализатора.', '', '', '', '', '', 'Встретьтесь с Ферозом у входа в Сады Катализации.', 45114),
(64838, 'ruRU', 'Был бы пилигрим, а путь найдется', 'Поговорите с обитателями Приюта Пилигрима.', 'Если обломки можно восстановить, кто-то в Приюте Пилигрима должен знать, как это сделать.\n\nСперва спроси у старейшины Нирава. Надеюсь, он не откажется нам помочь. Сегодня он какой-то нервный и рассеянный.\n\nКогда закончишь, найди меня в городе.', '', '', '', '', '', '', 45114),
(64837, 'ruRU', 'Путешествие пилигрима', 'Встретьтесь со старейшиной Арой в Приюте Пилигрима.', 'Приют Пилигрима – священное место для Просветленных. Обитающие там старейшины лучше других понимают суть творений Предвечных.\n\nУ них можно узнать о тех странных обломках, которые мы нашли.\n\nЯ буду ждать тебя там. Отсюда уже недалеко.', '', '', '', '', '', '', 45114),
(64836, 'ruRU', 'Пресечь в зародыше', 'Убейте Культиватора.', 'Раньше Двор Катализатора был мирным местом. Пилигримы веками приходили сюда любоваться чудесами Предвечных. Но здесь стало очень опасно. Теперь Культиватор нападает без всякого повода и не зная пощады. Он уже убил нескольких наших собратьев.\n\nЕго надо уничтожить.\n\nДругие старейшины со мной не согласятся. А я не согласна с ними.', '', 'Искаженное создание, опутанное колючими лозами и полное злобы.', 'Культиватор', '', '', 'Встретьтесь со старейшиной Арой у входа в Сады Катализации.', 45114),
(64835, 'ruRU', 'Сорвать с лозы', 'Спасите $2oa |4пропавшего пилигрима:пропавших пилигримов:пропавших пилигримов;.', 'Мне пришлось бежать через колючие заросли, уклоняясь от яростных плеточников.\n\nНо другим пилигримам повезло меньше. Пока я бежал, до меня доносились их крики ужаса и боли.\n\nПрошу, проберись в Сады. Спаси их, $n!', '', '', '', '', '', 'Встретьтесь с Ферозом у входа в Сады Катализации.', 45114),
(64834, 'ruRU', 'Торжественное сияние', 'Найдите объект, вызывающий реакцию обломков проводника.', 'Смотри-ка, $n! Обломки, которые ты $gсобрал:собрала;, излучают свет!\n\nПохоже, на них повлияло что-то в Приюте Пилигрима.\n\nВыясни, почему они так реагируют!', '', '', '', '', '', '', 45114),
(64833, 'ruRU', 'Объединяя разъединенное', 'Встретьтесь со старейшиной Арой над провизом эсперов.', 'Другие старейшины чтят творения Предвечных, следуя четким правилам.\n\nЯ же предпочитаю себя не ограничивать. Разные пути, единая цель. \n\nДавай вернемся туда, где ты в последний раз $gвидел:видела; Тюремщика.', '', '', '', '', '', '', 45114),
(64832, 'ruRU', 'Возвращение провиза эсперов', 'Убейте $3oa |4ненасытного клеща:ненасытных клещей:ненасытных клещей;, $2oa |4жаждущего душ поглотителя:жаждущих душ поглотителей:жаждущих душ поглотителей; и $1oa |4разрушителя реальности:разрушителей реальности:разрушителей реальности;.', 'Пожиратели заполонили провиз эсперов. Они налетели туда, словно рой голодных веспоидов.\n\nОни уничтожают местных автомов, а это точно не входило в замысел Предвечных. Придется очистить эти земли.\n\nСократи их число. Ради нашей безопасности и естественного порядка вещей.', '', '', '', '', '', '', 45114),
(64831, 'ruRU', 'Останки Предвечных', 'Добудьте $1oa |4обломок:обломка:обломков; проводника.', 'В провизе эсперов должны были остаться следы разрушений, учиненных Верными Утробе. Эти следы помогут нам понять, как последовать за Тюремщиком.\n\nДавай поищем вместе. Я почувствую магию Предвечных, если мы к ней приблизимся.', '', '', '', '', '', '', 45114),
(64830, 'ruRU', 'Вербовка Просветленных', 'Убедите старейшин Укрытия оказать вам помощь.', 'Сейчас у нас есть более насущные проблемы, чем судьба Сильваны.\n\nТюремщик уничтожил каналы Гармонии, чтобы мы не могли за ним последовать. \n\nПросветленные брокеры должны что-то знать об этих каналах и наверняка смогут помочь. Правда, сотрудничество с брокерами всегда подразумевает какую-то цену. \n\nСделай все, о чем они попросят. Нам нужна эта информация.', '', '', '', '', '', '', 45114),
(64829, 'ruRU', 'В поисках Тали', 'Найдите Тали у Свода Распределения.', 'После тысячелетий безмятежности силы Утробы принесли в Зерет Мортис страх и горе. Тали, одна из наших послушниц, особенно тяжело переносит недавние перемены. Не так давно она ушла от нас и с тех пор не вернулась. \n\nТы не $gмог:могла; бы проверить, все ли у нее в порядке? Когда ее видели в последний раз, она направлялась к погребенным в песках руинам.', '', '', '', '', '', 'Поговорите с Тали под Сводом Распределения.', 45114),
(64816, 'ruRU', 'На пороге реальности', 'Вернитесь в Зерет Мортис.', 'Пришло время отправиться за Зоваалом в самое сердце Темных Земель.\n\nНам надо вернуться в Зерет Мортис и покончить с этим.', '', '', '', '', '', 'Вернитесь в Зерет Мортис.', 45114),
(64813, 'ruRU', 'Корона воли', 'Восстановите Шлем Господства.', 'Создавая силу Господства, я не сумел предвидеть, какие страдания она причинит разным мирам. Не только царствам Темных Земель, но и вашему миру.\n\nПришло время перековать шлем, ставший символом губительной магии. Теперь он обретет иное предназначение.\n\nОн станет воплощением вашей несгибаемой воли и поможет наконец-то одолеть Зоваала.', '', '', '', '', '', '', 45114),
(64812, 'ruRU', 'Ковка Господства', 'Отправляйтесь в темницу Резчика Рун в Торгасте.', 'Мы собрали все, что нам нужно. Укрепили уцелевшую половину шлема сложными символами Предвечных, а осколки поменьше – нашими воспоминаниями. \n\nВоспоминаниями о нашем триумфе над силой Господства.\n\nКогда Примас восстановит шлем, мы сможем воспользоваться его объединенной силой.\n\nЭто очень опасно, но другой надежды у нас нет.', '', '', '', '', '', 'Отправляйтесь в темницу Резчика Рун в Торгасте.', 45114),
(64811, 'ruRU', 'Агрессивные раскопки', 'Соберите загадочные фразы.', 'Старейшина Эру сказала, что здесь можно найти самые сложные примеры языка Предвечных. \n\nНам придется пробиться в склепы и наполнить шлем мощью найденных фраз.\n\nА еще я никогда не думала, что мне доведется сражаться плечом к плечу с отцом. Но ставки так высоки, что мне кажется, будто я нахожусь именно там, где должна быть.\n\nЯ готова. Скажи, когда можно будет выдвигаться.', '', '', '', '', '', 'Вернитесь на Заброшенную площадку.', 45114),
(64810, 'ruRU', 'Подавить и уничтожить', 'Убейте Верных Утробе в Бесконечных песках.', 'То, что мы ищем, находится в склепах Бесконечных песков. Чтобы до них добраться, нужна поддержка армии.\n\nМы сможем уничтожить Верных Утробе лишь сообща. \n\nМне не терпится сразиться с ними.\n\nПомни, что они будут бессильны перед мощью обломка Шлема Господства.', '', '', '', '', '', '', 45114),
(64809, 'ruRU', 'Половина уравнения', 'Отправляйтесь на Заброшенную площадку.', 'Предположение Примаса о языке Предвечных подтвердилось. \n\nОднако этого может быть недостаточно. \n\nПока Примас разрабатывает свои планы, давай-ка поищем в Бесконечных песках частицы силы, которой можно будет напитать шлем. \n\nМы с Дарионом и Телией отправимся туда, чтобы помочь тебе расправиться с Верными Утробе.', '', '', '', '', '', 'Отправляйтесь на Заброшенную площадку.', 45114),
(64808, 'ruRU', 'То, что делает нас сильнее', 'Помогите провести ритуал и зарядить осколки Господства.', 'Как жаль, что я не узнал об этом месте раньше. Месте, где можно избавиться от кошмарной тьмы, что снедает тебя изнутри, где можно пересматривать и изгонять воспоминания...\n\nЯ готов пойти на все ради победы над Зоваалом, какой страшной ни была бы цена.\n\nДругого пути у нас нет.', '', '', '', '', '', '', 45114),
(64807, 'ruRU', 'То, что хотелось бы забыть', 'Помогите провести ритуал и зарядить осколки Господства.', 'Язык Прародителей непременно нам поможет, но есть и другая вещь, способная защитить от хватки Господства.\n\nНепоколебимая сила воли. \n\nТе из нас, кто уже смог пережить эту силу, обрели к ней некую сопротивляемость. Мы поделимся этим качеством, зарядив осколки своей энергией.\n\nПримас заверил меня, что такой ритуал сработает. Увы, другого выбора у нас нет. \n\nНадеюсь, результат оправдает испытанную боль.', '', '', '', '', '', '', 45114),
(64806, 'ruRU', 'Где живет память', 'Встретьтесь с верховным лордом Болваром в зале Первого Созерцания в Бастионе.', 'Кажется, я знаю, что от нас потребуется в Бастионе. Это будет нелегко.\n\nУ нас есть половина шлема – первое, что поможет нам против Господства. Но среди нас немало тех, кто пострадал от этой силы. И смог ее преодолеть. \n\nОна оставила на нас свой след. буквально на каждом.\n\nУ нас есть опыт успешной борьбы с влиянием Зоваала.\n\nДавай отправимся в Бастион, в зал Первого Созерцания.', '', '', '', '', '', 'Встретьтесь с верховным лордом Болваром в зале Первого Созерцания в Бастионе.', 45114),
(64805, 'ruRU', 'Ненаучный метод', 'Примените магию Расколотого шлема к активированному библиотекарю Лексикона и понаблюдайте за результатами.', 'Язык Предвечных не статичен, как большинство других языков. Он развивается.\n\nСамо собой, существа вроде часовых куда более развиты, чем те же цыпоиды. Их сложные мысленные процессы дают им врожденную сопротивляемость подавляющей магии чужаков. \n\nНо не стоит верить мне на слово. Давай все проверим! \n\nВ гроте обитает библиотекарь. Произнеси фразы, которые ты $gзаучил:заучила;, а затем примени к нему шлем.', '', '', '', '', '', '', 45114),
(64804, 'ruRU', 'Таинственный каталог', 'Запомните несколько фраз на Поляне Слов.', 'Здесь хранится множество различных текстов. Хм... О чем они? Понятия не имею!\n\nЯ лишь собираю библиотеку и составляю каталог. И сейчас, когда чужаки замышляют нарушить баланс Зерет Мортиса, важность моей работы сложно переоценить! Мы должны сохранить все то, что удалось найти.\n\nМожешь мне помочь! Отправляйся на поляну и заучи несколько фраз, а затем спускайся в грот. Там ты найдешь то, что поможет тебе еще лучше изучить силу Шлема.', '', '', '', '', '', 'Встретьтесь со старейшиной Эру в Гроте Слов.', 45114),
(64803, 'ruRU', 'Раз-раз, проверка', 'Испытайте силу расколотого Шлема на существах из Зерет Мортиса.', 'Существа Зерет Мортиса жили тут еще до того, как я создал магию Господства.\n\nМы уже видели, как на них воздействует мощь Зоваала, но, полагаю, нам еще многое предстоит узнать.\n\nИспытай Шлем на существах из Зерет Мортиса и постарайся узнать, что помогает им сопротивляться.', '', '', '', '', '', 'Встретьтесь со старейшиной Эру на Поляне Слов.', 45114),
(64802, 'ruRU', 'Здравствуй, Тьма', 'Испытайте сломанный Шлем Господства на Дарионе Могрейне.', 'Я создал магию Господства, чтобы наказать Зоваала.\n\nМой гнев вдохнул в нее силу, и теперь мы все платим за мою горыдню. Даже Вечные иногда ошибаются.\n\nНо отчаиваться пока рано.\n\nВозьми эту половину Шлема Господства и испытай на одном из своих собратьев. Если наполнить его достаточным количеством энергии, можно будет провести испытания где-нибудь еще в Зерет Мортисе.', '', '', '', '', '', '', 45114),
(64801, 'ruRU', 'Старейшина Эру', 'Отыщите старейшину Эру у Поляны Слов.', 'После того как мы заручились поддержкой Просветленных, мне удалось узнать кое-что об их исследованиях Зерет Мортиса.\n\nОни знают куда больше, чем нам рассказывают. Знают – и ничего не делают. Но там, где они лишь наблюдают, мы можем кое-что предпринять.\n\nВ глухом местечке под названием Поляна Слов живет старейшина по имени Эру. Возможно, она подскажет нам, как пользоваться языком Предвечных.\n\nОтыщи ее и уговори помочь.', '', '', '', '', '', 'Отыщите старейшину Эру у Поляны Слов в Зерет Мортисе.', 45114),
(64800, 'ruRU', 'Наш последний вариант', 'Выслушайте план действий.', 'Зоваал преградил нам путь. Чтобы с ним справиться, необходимо преодолеть силу Господства.\n\nДля этого нам надо понять, как она действует. \n\nЭта магия создана Примасом Малдраксуса, он наверняка сможет посвятить в ее суть.\n\nЯ попросил Телию принести осколок Шлема Господства в Зерет Мортис. Боюсь и подумать, что произойдет, если я снова прикоснусь к нему... \n\nДавай решим, что делать дальше.', '', '', '', '', '', '', 45114),
(64799, 'ruRU', 'Сломанная корона', 'Поговорите с Андуином Ринном в Геометрической пещере.', 'Наши союзники вернулись из Гробницы Предвечных и привели одного нашего знакомого.\n\nАндуин... Какие ужасы ему пришлось испытать... \n\nЯ не хотел бы бередить такую свежую рану, но мы должны расспросить его. Тюремщик преградил нам путь в Гробнице, и мы тоже станем жертвой сил Господства, если продолжим погоню, не подготовившись.\n\nВозможно, лишь Андуин способен нам помочь.', '', '', '', '', '', '', 45114),
(64798, 'ruRU', 'Через что мы только ни прошли', 'Убейте чудовище из Утробы и наделите силой последний осколок.', 'Теперь я понимаю. Каждый из тех, кого коснулась магия Господства, нашел источник внутренней силы, чтобы бороться. Благородство, жажда мести... что угодно.\n\nЯ все еще здесь, несмотря на все, что мне пришлось испытать.\n\nИ если Сильване удалось найти единомышленников, то кто-нибудь поверит и в меня.\n\nЯ готов попробовать снова. В этот раз я выдержу любое испытание.', '', '', '', '', '', '', 45114),
(64780, 'ruRU', 'Стальная проблема', 'Подберите $1oa |4осколок:осколка:осколков; стали Утробы и сбросьте их с уступов.', 'Зерет Мортис – священное место. Здесь не должны появляться разломы. Их что-то создает. \n\nНайденный тобой металл полон магии Утробы. Это он позволяет пожирателям открывать разломы. Вот как они обходят нашу защиту.\n\nЗдесь повсюду разбросаны осколки стали Утробы. Собери их. Затем сбрось с уступов. Тогда пожиратели больше не смогут открывать разломы.', '', '', '', '', '', '', 45114),
(64779, 'ruRU', 'Фунт мяса', 'Добудьте $1oa |4кусок:куска:кусков; искаженной плоти у пожирателей в Крае Зоваала.', 'Обычно автомы избавляют нас от угроз. Но автомов больше нет. Мы должны сами себя защитить. Нам нужна магия.\n\nПожиратели поглотили магию из сфер. Они мутировали и исказились. Но также наполнились магией.\n\nПринеси их плоть. Мы извлечем из нее магию. С ней мы победим пожирателей.', '', '', '', '', '', '', 45114),
(64778, 'ruRU', 'Разведка разломов', 'Изучите $1oa |4искаженный разлом:искаженных разлома:искаженных разломов;.', 'Пожиратели – серьезная проблема. Разломы – проблема еще серьезнее. \n\nИз них появляются новые пожиратели. Мы должны их закрыть. Для этого нужна информация. \n\nВозьми этот крещендал. Изучи с его помощью разломы. И возвращайся с новой информацией.', '', '', '', '', '', '', 45114),
(64775, 'ruRU', 'На службе Утробе', 'Убейте Развоплотителя и обыщите его.', 'В пещере поджидает пожиратель. Из-за него там образовался разлом. Обычно в Зерет Мортисе такое невозможно.\n\nВойди в пещеру и уничтожь пожирателя. Потом поищи вокруг зацепки. Постарайся узнать, как ему удалось открыть разлом.\n\nИ будь $gосторожен:осторожна;. Это чудище отличается от остальных. Оно впитало в себя магию Предвечных. Такого еще никогда не случалось. Будь $gготов:готова; ко всему.\n\nЯ останусь здесь и буду защищать джиро.', '', 'Новый вид пожирателя, поглотивший магию Предвечных.', 'Развоплотитель', '', '', '', 45114),
(64773, 'ruRU', 'Руководство джиро: \"Как не стать чьим-то обедом\"', 'Сократите число пожирателей на Террасе Формирования.', 'На нас напали пожиратели. Так много, что стражи были бессильны. Они все еще ищут, чем поживиться.\n\nМы в опасности. Сократи их число.\n\nТогда они нас не съедят.', '', '', '', '', '', '', 45114),
(64772, 'ruRU', 'Разорванный круг', 'Найдите выживших джиро и убедите их встретиться у входа в пещеру.', 'Здесь работают джиро из Круга Олеа. Мы создаем...\n\n<Джиро ненадолго замолкает.>\n\nОни... создают для Кузни новые земли и существ.\n\nСюда ворвались пожиратели, но некоторые джиро еще живы. $gТы должен:Ты должна; их найти. Вели им собраться у входа в пещеру, что на севере отсюда. Я расчищу путь.\n\nТолько не говори им, что это я тебя послала. Они не захотят меня видеть.', '', '', '', '', '', '', 45114),
(64767, 'ruRU', 'Последняя песня', 'Стойте рядом с Кодахом и отражайте атаки врагов, чтобы отвоевать Проторепозиторий.', 'Сервиторы недостаточно сильны для восстановления репозитория. Но задача должна быть выполнена.\n\n$gСмертный должен:Смертная должна; держаться рядом и обеспечивать защиту во время восстановления.\n\nИдем.', '', '', '', '', '', 'Поговорите с Тали в Проторепозитории.', 45114),
(64766, 'ruRU', 'Запрос доступа', 'Найдите протоархитектора в зале Ваяния и получите матрицу восстановления.', 'Только архитектор владеет необходимой матрицей восстановления. Архитектор восстановит Проторепозиторий.\n\n$gСмертный:Смертная; получит доступ к залу Ваяния и доложит архитектору о статусе задачи. Архитектор восстановит репозиторий.\n\nЗадача будет выполнена.', '', 'Главный инженер Свода Распределения создал немало чертежей протожизни.', 'Протоархитектор', '', '', 'Поговорите с Кодахом в Проторепозитории.', 45114),
(64763, 'ruRU', 'Режим обслуживания', 'Настройте $1oa |4терминал:терминала:терминалов; подачи энергии под Сводом Распределения.', 'Архитектор обозначил несколько задач. \n\nБеречь себя. \n\nВосстановить Проторепозиторий, когда станет безопасно.\n\n$gСмертному:Смертной; известны шифры. $gСмертный:Смертная; поможет выполнить задачи.\n\nНужно настроить терминалы подачи энергии. Для каждого терминала требуется кодекс. Нужные кодексы похитили захватчики. \n\nИди.', '', '', '', '', '', 'Поговорите с Кодахом в Проторепозитории.', 45114),
(64762, 'ruRU', 'Оживление сильнейших', 'Восстановите скрытного сервитора под Сводом Распределения.', 'Сердечник переполняет энергия!\n\nВосстанови автома с его помощью. Надеюсь, после этого он перестанет нас опасаться.\n\nНо будь $gосторожен:осторожна;. Сила Предвечных не предназначена для таких, как мы.', '', '', '', '', '', '', 45114),
(64761, 'ruRU', 'Сердечные вопросы', 'Зарядите истощенный сердечник автома возле убитых зверей под Сводом Распределения.', 'Бедняжка.\n\nМы не должны вмешиваться в дела священных служителей, но... старейшины ведь не осудят нас, если мы поможем ему выжить? Так мы защитим это царство, а не изменим его.\n\nТо есть... мне так кажется. \n\nМы можем восполнить его энергию. Этот истощенный сердечник послужит проводником. Думаю, у оживленных созданий, обитающих неподалеку, найдется достаточно энергии.', '', '', '', '', '', '', 45114),
(64759, 'ruRU', 'Не металлолом, а раритет!', 'Добудьте символы у $1oa |4истощенного сервитора:истощенных сервиторов:истощенных сервиторов; у Свода Распределения.', 'Этот автом прятался здесь! Боюсь, он не решится принять нашу помощь.\n\nНе знаю, правильно ли будет так поступить, но если убедить этого сервитора, что ты тоже здесь служишь, то он не станет тебя опасаться. \n\nЕсли сможешь, перепиши символы, нанесенные на таких же автомов снаружи. Многих из них исказила Утроба, но ранее я заметила в песках некоторых автомов, чьи символы остались нетронутыми.', '', '', '', '', '', '', 45114),
(64745, 'ruRU', 'Самоотверженное хранение', 'Найдите украденный артефакт под Сводом Распределения и верните его на прежнее место.', 'Раньше здесь обитало множество автомов. Они пели, строили и выполняли любую прихоть Предвечных. Но пришли захватчики из Утробы и всех перебили.\n\nПоследними пали автомы, защищавшие что-то важное в той постройке неподалеку. \n\nЯ видела, как один из Верных Утробе забрал устройство, которое лежало у двери. Старейшины велели нам не трогать артефакты, но что плохого в том, чтобы вернуть украденное?', '', '', '', '', '', '', 45114),
(64739, 'ruRU', 'Край Зоваала', 'Следуйте за Ханоа Изгнанницей и выслушайте ее историю.', 'Я помню этот металл. Видела его, когда меня коснулась магия Утробы. Когда меня отсекли...\n\nЯ покажу тебе, где это случилось. Идем. Я расскажу тебе, что со мной произошло.', '', '', '', '', '', '', 45114),
(64733, 'ruRU', 'Потусторонняя помощь', 'Поговорите с представителями Просветленных, вентиров, некролордов и ночного народца.', 'Чтобы прорваться через армии Верных Утробе, нам нужна помощь всех ковенантов.\n\nЯ поговорю с кириями, а вы с Пелагием возьмите на себя остальных. Но сначала спроси Фирима, нельзя ли заручиться поддержкой Просветленных.', '', '', '', '', '', 'Встретьтесь с войсками ковенантов на Заброшенной площадке.', 45114),
(64731, 'ruRU', 'Каждая душа', 'Найдите способ создать нового Арбитра.', 'Пока у нас нет Арбитра, способного остановить поток душ в Утробу, Темные Земли не могут надеяться на спасение.\n\nЯ не верю, что уже все потеряно. Должен быть какой-то выход. Как ты думаешь?', '', '', '', '', '', '', 45114),
(64730, 'ruRU', 'Поворотный момент', 'Исследуйте сосуд и автомов-провидцев.', 'Пауза, ни вдоха, ни выдоха. Мелодия еще звучит. Циклу нужен голос.\n\n<Вы не понимаете, что Саезура хочет этим сказать. Может, стоит провести ритуал заново? Вы решаете начать с сосуда и провидцев.>', '', '', '', '', '', 'Поговорите с Клейей.', 45114),
(64729, 'ruRU', 'На кону вечность', 'Вернитесь в пещеру Изгнанника.', 'Песнь дописана, и ее гармония восстановлена. Но в Зерет Мортисе по-прежнему царит хаос.\n\nЗа этими стенами все еще слышны напевы раздора. Надо уходить, пока они нас не настигли.\n\nПоговори с тем, кого называешь Фиримом. Он откроет путь.', '', '', '', '', '', 'Встретьтесь с Клейей в пещере Изгнанника.', 45114),
(64728, 'ruRU', 'Позабытые знакомые', 'Завершите ритуал.', 'Время пришло. Песнь создаст новую жизнь. Скажи, когда можно будет начинать.', '', '', '', '', '', '', 45114),
(64727, 'ruRU', 'Бесконечный круговорот', 'Сопроводите Саезуру в центр Склепов Вечных.', 'Творение зовет – слышишь? Но тьма по-прежнему сильна, и она оскверняет древнюю мелодию.\n\nЧтобы вновь приступить к ковке, нужно восстановить мир. Задача Пилигрима – идти вперед и защищать.\n\nНам еще много всего предстоит сделать. Веди.', '', '', '', '', '', 'Встретьтесь с Саезурой в центре Склепов Вечных.', 45114),
(64726, 'ruRU', 'Порядок вещей', 'Запечатайте разломы с помощью $13oa сдерживающих сфер.', 'Кто-то пытался манипулировать сущностями древних душ – они сочатся из каждой комнаты. Залы нужно восстановить, а поток душ – перенаправить.\n\nСферы – вот ключ к спасению. Запечатай разломы и восстанови поток, а затем можно будет наполнить сосуд.', '', '', '', '', '', '', 45114),
(64725, 'ruRU', 'Непростительное вторжение', 'Избавьтесь от $1oa |4подчиненного автома:подчиненных автомов:подчиненных автомов; и $2oa |4темного провидца - осквернителя:темных провидцев - осквернителей:темных провидцев - осквернителей;.', 'Тьма наполняет эти залы диссонансом. Верные Утробе вытягивают из воздуха саму жизнь, а взамен оставляют лишь страдания. Так быть не должно.\n\nЧтобы песня снова зазвучала, для начала необходима тишина. Верных Утробе надо уничтожить.', '', '', '', '', '', '', 45114),
(64723, 'ruRU', 'Проект по восстановлению', 'Поговорите с Саезурой.', 'Без Арбитра само существование Темных Земель оказалось под угрозой. Души текут в Утробу, их поток никто не контролирует.\n\nКак заметила Саезура, в обычных обстоятельствах Зерет Мортис изготовил бы новую сущность, которая заменила бы Арбитра. Но, боюсь, силы Тюремщика ослабили это царство до такой степени, что это уже невозможно.\n\nПришла пора взять дело в свои руки и вернуть порядок в Темные Земли! Поговори с Саезурой и узнай, с чего нам следует начать.', '', '', '', '', '', '', 45114),
(64722, 'ruRU', 'В обиталище вечности', 'Отправляйтесь в бой верхом на Кбато, победите Верных Утробе в Бесконечных песках и откройте проход в Склепы Вечных.', 'Время настало, $gсмертный:смертная;. Собранной тобой армии должно хватить для того, чтобы разбить Верных Утробе и добраться до Склепов. Однако проникнуть в них будет не так-то просто. Верные Утробе заблокировали вход.\n\nТы отправишься в бой верхом на Кбато. Избавься от врагов и уничтожь питающие преграду устройства.', '', '', '', '', '', 'Встретьтесь с Фиримом и остальными в Склепах Вечных.', 45114),
(64720, 'ruRU', 'Прорубить дорогу', 'Убейте оракулов Зокета и Воракси.', 'Пилигрим! Разведчики доложили, что Верные Утробе подчинили себе двух автомов-оракулов. Если им не помешать, они откроют врагам нашу стратегию и конечную цель.  \n\nПрежде чем направляться в Склепы, мы должны избавиться от оракулов. Без их помощи Верные Утробе не узнают, что мы замыслили, пока не станет слишком поздно.\n\nВозьми с собой Эмени. Она так и рвется в битву.', '', '', '', '', '', '', 45114),
(64718, 'ruRU', 'Ключи к победе', 'Освободите из заточения $1oa |4автома-провидца:автомов-провидцев:автомов-провидцев;.', 'Песня... не завершена. Ей не хватает гармонии. Ищи тех, кто смотрит в будущее. Пусть они послужат циклу.\n\nУ Верных Утробе есть особые пленяющие ключи. Забери ключи, освободи провидцев.', '', '', '', '', '', '', 45114),
(64713, 'ruRU', 'Сбор обломков', 'Добудьте $1oa |4фрагмент сферы:фрагмента сферы:фрагментов сферы;.', 'С помощью сфер мы создаем в Кузне землю. Но магия привлекает пожирателей. Чтобы до нее добраться, они разрывают сферы на части. Нужно собрать осколки.\n\nПоищи фрагменты вокруг сфер. Принеси нам все, что найдешь.', '', '', '', '', '', '', 45114),
(64706, 'ruRU', 'Вопрос мотивации', 'Отправьте $1oa |4мотивированный автом:мотивированных автомов:мотивированных автомов; к Фириму.', 'В этих песках много неактивных великанов, смертное существо. Но я знаю, как вернуть их в строй. \n\nВ этом нам помогут маленькие автомы, которые прячутся по всей пустыне. Возьми мой мотиватор и убеди их нам помочь. Если соберем достаточно энергии, то зарядим эти побежденные громадины и усилим наше войско.\n\nОтправляй мотивированных автомов ко мне, я найду им применение!', '', '', '', '', '', '', 45114),
(64648, 'ruRU', 'Что посеешь, то и пожнешь', 'Уничтожьте заряженного конструктора.', 'Мы сказали конструктору, что запустим Литейную и приведем это место в порядок.\n\nНужно остановить его и защитить новых автомов.', '', '', '', '', '', '', 45114),
(64647, 'ruRU', 'Странные шестеренки', 'Добудьте $1oa |4витое семя:витых семени:витых семян; у автомов в Литейной Цветения.', '<Удивительно, но семя во внутренностях автома все еще полно жизни.\n\nНеужели все местные автомы устроены так же?>', '', '', '', '', '', '', 45114),
(64646, 'ruRU', 'Постепенное улучшение', 'Активируйте $1oa |4проводник:проводника:проводников; в Литейной Цветения.', 'Чтобы Литейная заработала, нужно восстановить в ней энергию. Энергия подается через проводники.\n\nМы знаем, как их активировать. Расчисти дорогу, и мы сможем все начать сначала.', '', '', '', '', '', '', 45114),
(64645, 'ruRU', 'Момент истины', 'Следуйте за джиро из Круга Ко в Неукротимых зарослях.', 'Конструктор готов действовать.\n\nСейчас мы откроем Литейную Цветения и вернем этим землям первозданный облик.\n\nМы сможем все начать сначала.', '', '', '', '', '', '', 45114),
(64644, 'ruRU', 'Всплеск вечности', 'Помогите Мерцающей Тростинке набрать воду из пруда в Неукротимых зарослях.', 'Я мало что знаю об этом месте и его обитателях, зато отлично разбираюсь в магии! И чувствую, что вода неподалеку пропитана древней силой.\n\nМожет быть, она поможет?\n\nДавай-ка проверим тот пруд!', '', '', '', '', '', 'Залейте извечную воду в неподвижного автома.', 45114),
(64643, 'ruRU', 'Поиски решения', 'Добудьте $1oa |4внутренний компонент:внутренних компонента:внутренних компонентов; у брошенных автомов в Неукротимых зарослях.', 'Это место было создано с помощью Литейной Цветения. От нее же зависит состояние местных автомов, существ и растений.\n\nЭтих зарослей тут быть не должно.\n\nНужно попасть в Литейную и все исправить. Этот конструктор сможет пробиться внутрь, если его активировать.\n\nМногие местные автомы уже давно не действуют. Найди у них нужные детали.', '', '', '', '', '', '', 45114),
(64642, 'ruRU', 'Зачистка руин', 'Убейте $1oa |4существо:существа:существ; в Неукротимых зарослях.', 'Эти земли слишком долго были заброшены. Местные растения вышли из-под контроля.\n\nИсправить ситуацию можно только в Литейной Цветения.\n\nНо сначала... очисти это место. Уничтожь мутантов.', '', '', '', '', '', '', 45114),
(64641, 'ruRU', 'Таинственная поросль', 'Доберитесь до Неукротимых зарослей вместе с Мерцающей Тростинкой.', 'Там, наверху, находится сияющий источник силы. Меня тянет к нему, словно мотылька к огоньку!\n\nВот бы посмотреть, что там. Пойдешь со мной? Будет весело!', '', '', '', '', '', '', 45114),
(64592, 'ruRU', 'Защита истории', 'Помогите Маи Обет изучить $1oa |4журнал:журнала:журналов; терраформирования в Бесконечных песках.', 'Из-за чужаков в Бесконечных песках стало слишком опасно. Теперь мы не можем добраться до журналов терраформирования, в которых записана важная историческая информация.\n\nТы сможешь это сделать?\n\nПомоги Маи Обет собрать исторические записи в Бесконечных песках.', '', '', '', '', '', '', 45114),
(64579, 'ruRU', 'Пустые хлопоты', 'Используйте протозонд Фирима и добудьте $1oa |4оставшуюся неочастицу:оставшиеся неочастицы:оставшихся неочастиц; из Кузен Прародителей.', 'Те огромные металлические сферы, встречающиеся по всему Зерет Мортису, – это истощенные кузни, которые участвовали в процессе творения. \n\nВ этих опустевших оболочках все еще остались ценные материалы, которые могут нам пригодиться.\n\nПодойди к сфере и с помощью моего клапана для Кузни собери из нее оставшиеся неочастицы. Возможно, тебе удастся добыть и другие протоматериалы!', '', '', '', '', '', '', 45114),
(63522, 'ruRU', 'Честная гонка', 'Честно посоревнуйтесь с Ванделлором в беге на скорость.', 'Кириям иногда попадаются души, которые отказываются проходить за грань. Я могу помочь тебе.\n\nНо прежде чем наделить твое оружие такой силой, мне надо испытать честность твоих намерений и чистоту сердца.\n\nПроведем состязание в беге на скорость. Звони в колокола по пути. Если у тебя чистое сердце, их звон поможет бежать быстрее. Незадолго до финиша надо позвонить как минимум в пять колоколов, иначе победа не засчитается.\n\nНе отвлекайся и не срезай путь. И не пытайся схитрить – все равно не получится.\n\nНачнем?', '', '', '', '', '', '', 45114),
(63519, 'ruRU', 'Нечестный бой', 'Докажите свою силу мастеру боя Сану.', 'Трусливый таракан, который обманом бежит от славной смерти? Ха!\n\nЯ знаю, как сразить его на месте. Но я не отдам такую мощь тому, кто не сумеет по-настоящему ею воспользоваться.\n\nДокажи мне свою силу в бою! Если победишь, я так и быть усилю твой протазан.', '', 'Задача: впечатлить.', 'Мастер боя Сан', '', '', '', 45114),
(63501, 'ruRU', 'Не кража, а заимствование', 'Найдите в Тенегорне $1oa |4слиток:слитка:слитков; Черной наковальни, бурлящий огненный сердечник и раскаленный резец.', '<На небрежных чертежах изображены схемы оружия Тургадена, но разобраться в них очень сложно. Поля вкривь и вкось исписаны пометками и уточнениями, которые Тургаден оставил для себя.\n\nВам в глаза бросились две записи. В одной говорится, что он одолжил инструмент для гравировки Кейси Кузне Гнева, дрессировщице гончих недр. Другая – напоминание о том, что надо узнать, сколько элементалей \"Угрюмый обжора\" задействует при варке пива.>', '', '', '', '', '', 'Вернитесь к тану наковальни Тургадену.', 45114),
(63494, 'ruRU', 'Чертежи тана наковальни', 'Узнайте, кому Тургаден проиграл чертежи в трактире \"Угрюмый обжора\".', 'Я смотрю, тебе нравится наше оружие. Между прочим, это я его ковал!\n\nСейчас у меня есть чертежи для посоха, одноручного топора и щита... Если хочешь, могу тебе их сделать!\n\nНу, то есть... мог бы. Я, к сожалению, проиграл чертежи в \"Угрюмом Обжоре\". Если ты мне их вернешь и соберешь материалы, я с удовольствием выкую тебе оружие!', '', '', '', '', '', '', 45114),
(63490, 'ruRU', 'Рыцарь крови', 'Примите почести от леди Лиадрин в Луносвете.', 'Протазан истратил всю свою силу, но победа за нами! Без Вората с Плетью будет гораздо проще разобраться – благодаря тебе.\n\nНайди меня в Луносвете. Твой героизм заслуживает награды.', '', '', '', '', '', '', 45114),
(63489, 'ruRU', 'Долгожданное правосудие', 'Убейте Вората.', 'От Плети на Тропе Мертвых только клочья летели, но главная цель еще впереди. Пора испробовать твое оружие против самого Вората.\n\nПокончим с ним вместе.', '', 'Все этапы плана приведены в действие. Пора покончить с этим злодеем.', '', '', '', '', 45114),
(63488, 'ruRU', 'Я – клинок Света', 'Убейте усиленным протазаном солдат Плети на Тропе Мертвых.', 'Пора проверить эту мощь и испытать себя в настоящем бою.\n\nВозьми усиленный протазан и выкоси армию Плети под корень!\n\nВстретимся у врат Смертхольма.', '', '', '', '', '', '', 45114),
(63487, 'ruRU', 'Возвращение в Призрачные земли', 'Возвращайтесь к леди Лиадрин в Транквиллион.', 'Какая сила! Даже Ворат ни за что не выстоит против мощи такого оружия. \n\nПутешествие в Темные Земли оказалось не напрасным. Протазан готов.\n\nДавай вернемся к леди Лиадрин в Транквиллион. Надеюсь, еще не слишком поздно все изменить!', '', '', '', '', '', 'Возвращайтесь к леди Лиадрин в Транквиллион.', 45114),
(63486, 'ruRU', 'Непреклонная воля', 'Отправляйтесь в Театр Боли Малдраксуса.', 'Судя по всему, сан\'лейн обратился к темной магии. Именно она не дает ему умереть.\n\nНам уже встречались те, кто так обращается с магией. Малдраксийцы познали смерть во всех проявлениях и научились ее побеждать. Один из домов наверняка сумеет помочь нам.\n\nОтправляйся в Малдраксус и найди силу, которая прервет этот противоестественный цикл.', '', '', '', '', '', 'Отправляйтесь в Театр Боли Малдраксуса.', 45114),
(63485, 'ruRU', 'Честное сердце', 'Отправляйтесь в рощу Агфии в Бастионе.', 'Чтобы уничтожить Вората, придется наполнить протазан силой. Но самый, казалось бы, простой способ тут не годится. Мы хорошо усвоили предыдущий урок.\n\nКирии Бастиона превосходно умеют направлять души по нужному пути. Может, они согласятся поделиться с нами своей силой.\n\nОтправляйся в Бастион и придумай, как усилить протазан.', '', '', '', '', '', 'Отправляйтесь в рощу Агфии в Бастионе.', 45114),
(63484, 'ruRU', 'Оружие рыцаря', 'Сходите наверх и заберите протазан из Транквиллиона.', 'Видимо, этот сан\'лейн решил за счет Плети приумножить свою собственную силу. Сколько его ни убивай, он все равно вернется.\n\nНам нужно оружие, которое прикончит его раз и навсегда.\n\nИ у меня есть предложение. Наверху ты найдешь совсем новый протазан. Оружие пока не закаляли магией – нам еще предстоит раскрыть все его возможности. Этот протазан станет нашим орудием Света.', '', '', '', '', '', '', 45114),
(63483, 'ruRU', 'Укрепления волхвов', 'Помогите Этасу и Роммату закрепиться в Транквиллионе.', 'Это был точно рассчитанный удар... Я всерьез подозреваю, что Плетью управляет какое-то могущественное существо.\n\nС тех пор как раскололся Шлем Господства, теоретически ничто не мешало кому-то другому подчинить нежить своей воле – как минимум на время.\n\nМы с Ромматом поможем защитить Транквиллион, но сначала надо ослабить вражеский натиск. \n\nОбустрой нам командный пункт. Посмотрим, не появится ли их лидер.', '', '', '', '', '', '', 45114),
(63482, 'ruRU', 'Смерть Плети', 'Убейте солдат Плети в Транквиллионе.', 'Я не помню таких громадных армий нежити с тех пор, как...\n\n<Лиадрин встряхивает головой и собирается с духом.>\n\nТак, ладно. Что толку вспоминать.\n\nСейчас наша главная задача – сократить число врага. Тогда мы сможем разобраться, что – или кто – стоит за всем этим наступлением. \n\nУбей как можно больше нежити.', '', '', '', '', '', '', 45114),
(63481, 'ruRU', 'Осажденный Транквиллион', 'Пройдите через портал в Транквиллион.', 'Роммат открыл нам мгновенный переход до Транквиллиона. Но предупреждаю: там сейчас самая настоящая бойня.\n\nЯ пройду в портал сразу за тобой.\n\nИ знаешь что, $n... присмотри за Саландрией. Она отлично показала себя на тренировках, но еще ни разу не бывала в настоящей битве.', '', '', '', '', '', '', 45114),
(63480, 'ruRU', 'Инструктаж', 'Выслушайте отчет.', 'У нас совсем немного времени. \n\nПлеть напала на Транквиллион, а противостоять ей некому.\n\nНадо действовать решительно.', '', '', '', '', '', '', 45114),
(63479, 'ruRU', 'Призыв матриарха', 'Встретьтесь с леди Лиадрин в Луносвете.', 'Здравствуй, $n.\n\nПерейдем сразу к делу – ты срочно $gнужен:нужна; в Луносвете. \n\nНа Кель\'Талас надвигается новая волна Плети. Если не принять меры, она сметет наши силы сопротивления. Мы должны сдержать врага!\n\nНайди меня в Зале Крови, чтобы обсудить детали.', '', '', '', '', '', 'Встретьтесь с леди Лиадрин в Луносвете.', 45114),
(57766, 'ruRU', 'Война с Ордой', 'Поговорите с адмиралом Гэррик и узнайте, что произошло между Ордой и Альянсом.', 'Вижу, тебя хорошо обучили, |3-6($c).\n\nТвоим навыкам найдется применение. Война Альянса с Ордой разгорелась вновь... а мы потеряли много хороших солдат.\n\nКороль Андуин укрепляет нашу армию перед предстоящей операцией. Я сказала ему, что ты тоже подойдешь.\n\nПеред встречей с ним я введу тебя в курс произошедшего.', '', '', '', '', '', '', 45114),
(54781, 'ruRU', 'UNUSED', 'Отразите нападение Орды на Тирагардское поморье.', 'Силы Орды атакуют Тирагардское поморье. Пусть они пожалеют о том, что ступили на нашу землю!', '', '', '', '', '', '', 45114),
(54603, 'ruRU', 'Надзиратель Крикс', '', '', '', '', '', '', '', '', 45114),
(54483, 'ruRU', 'Обучение портняжному делу', '', '', '', '', '', '', '', '', 45114),
(54473, 'ruRU', 'Формулы зачарования', '', '', '', '', '', '', '', '', 45114),
(54391, 'ruRU', 'Пожертвования на битву за Темные берега: золотистый берилл стремительности', 'Принесите $1oa |4порцию:порции:порций; филе с приправами Сенедрасу в гавань Боралуса.', 'Вкусное и питательное мясо – именно то, что нужно нашим союзникам, чтобы набраться сил перед битвой. К тому же из него получается отличная похлебка, которую обожают воины в холодные и ветреные ночи.\n\nЕсли принесешь мне несколько свежих порций филе с приправами, я с радостью передам их офицерам снабжения.', '', '', '', '', '', '', 45114),
(54388, 'ruRU', 'Пожертвования на битву за Темные берега: водолазный шлем из поблескивающей чешуи', 'Принесите $1oa шт. \"Чары для кольца – знак критического удара\" Мэй Жезловихлик в гавань Боралуса.', '', '', '', '', '', '', '', 45114),
(54381, 'ruRU', 'Пожертвования на битву за Темные берега: ультрамариновые чернила', 'Принесите $1oa |4запеченного сома:запеченных сома:запеченных сомов; Сенедрасу в гавань Боралуса.', 'Приветствую тебя, $gпутник:путешественница;.\n\nМне поручили следить, чтобы наши запасы провизии не иссякали. А сейчас у нас заканчивается рыба. У тебя не найдется чего-нибудь, чтобы пожертвовать нам?', '', '', '', '', '', '', 45114),
(53321, 'ruRU', 'Сияющий монелит', '', '', '', '', '', '', '', '', 45114),
(53317, 'ruRU', 'Твердое штормовое серебро', '', '', '', '', '', '', '', '', 45114),
(49661, 'ruRU', 'Яйца с местных пляжей', 'Добудьте $1oa |4яйцо:яйца:яиц; чешуйника в гнездах чешуйников.', 'В мире нет ничего лучше, чем блюда из превосходных, свежайших ингредиентов!$b$bДорогой друг, я вышел на охоту. На охоту за идеальными яйцами! Я слышал о яйцах угря. Нежная текстура, легкие нотки морской соли... воистину уникальный вкусовой букет! Мне непременно нужно их достать!$b$bЗдешние угри откладывают яйца на суше, прежде чем вернуться в море. Пожалуйста, принеси мне эти яйца – тогда я смогу создать изысканнейший из омлетов!', '', '', '', '', '', '', 45114),
(49464, 'ruRU', 'Хвосты завролисков', 'Добудьте $1oa |4хвост:хвоста:хвостов; лишайникового завролиска.', 'Есть подвиг, который под силу только самым решительным кулинарам. Сливки общества Кул-Тираса без ума от одного деликатеса. Они платят кучу монет, чтобы попробовать его с теми специями или в том виде, который им больше по душе.$b$bКонечно, я имею в виду хвост завролиска.$b$bЯ должен открыть лучший способ готовить это модное блюдо! Варить? Тушить? Томить на медленном огне? Наверное, лучше всего подойдет варка на пару или бланшировка!$b$bНесомненно, мне понадобится несколько хвостов для экспериментов.', '', '', '', '', '', '', 45114),
(49053, 'ruRU', 'Дозорный', '', '', '', '', '', '', '', '', 45114),
(47894, 'ruRU', 'Распрыжка', '', '', '', '', '', '', '', '', 45114),
(47695, 'ruRU', 'Сигнал тревоги', 'Убейте $1oa |4поющую сирену:поющих сирен:поющих сирен; на берегу Туманных Скал.', 'Беда с этими сиренами! Они крадут мужчин, и все их жертвы исчезают навсегда. Как прикажете в таких условиях быстро доставлять грузы в Боралус?$b$bСлушай, раз ты все равно туда собираешься... может, избавишь нас хотя бы от нескольких сирен?', '', '', '', '', '', '', 45114),
(44583, 'ruRU', 'Осквернение огня', '', '', '', '', '', '', '', '', 45114),
(43419, 'ruRU', 'К свету', '', '', '', '', '', '', '', '', 45114),
(42953, 'ruRU', 'ОЧЕНЬ ОПАСНА: стражница душ Альдора', '', '', '', '', '', '', '', '', 45114),
(41761, 'ruRU', 'Зимний выпас лосей', 'Спасите 4 талбука на ферме Кууроса.', 'Эта ферма принадлежит Кармаану, моему отцу. Мы держим скот – в основном талбуков. Видать, один из стручлингов открыл дверь их загона, и они все сбежали!$B$BЭти маленькие твари могли бы перебить их и в загоне, но, видать, решили \"поохотиться\". И боюсь, что еще немного, и я стану их следующим \"блюдом\"!$B$BМожет, ты сгонишь сбежавших талбуков обратно сюда? Я сам не справлюсь, а если папа узнает, он с меня три шкуры сдерет!', '', '', '', '', '', '', 45114),
(41253, 'ruRU', 'Идущий на нерест лосось Крутогорья', '', '', '', '', '', '', '', '', 45114),
(33782, 'ruRU', 'Сохранение равновесия', 'Убейте Хрустохвата на Ягодной поляне.', 'Ты только посмотри на эти зубы! Эти отметины указывают на то, что на кроколисков нападает кто-то из их же рода. Когда самки кроколисков достигают определенного размера, они начинают сражаться со своими сородичами за власть.$B$BМой долг как охотника – проследить за тем, чтобы равновесие было восстановлено. Пусть это будет моей благодарностью за жертву, которую они принесли ради меня.$B$BВыследи эту тварь и убей ее, а я пока займусь своими ранами. Скорее всего, она сейчас где-то на дальней границе поляны.', '', '', 'Хрустохват', '', '', '', 45114),
(31762, 'ruRU', 'Рассыпающийся колосс', 'Уничтожьте колосса Шао-Тень.', 'Могу все же возвели свою гигантскую каменную статую, и теперь собираются послать ее на борьбу с нами.$B$BВ ответ я собираюсь послать тебя на борьбу с ней.$B$BОна спускается с Золотой лестницы. Поставь ее на колени!', '', '', '', '', '', '', 45114),
(31756, 'ruRU', 'Кажется, дождь собирается', 'Уничтожьте призывающие бурю посохи.', 'Могу призывают какую-то зловещую бурю на Золотой лестнице. Честно говоря, мне не нравится, когда могу заваривают кашу с громом и молниями. Мы должны остановить их.$B$BНайти их призыватели бурь не составит труда – из них вырываются разряды молний. Не согласишься ли ты уничтожить их? Тогда мне будет спаться гораздо спокойнее.', '', '', '', '', '', '', 45114),
(30630, 'ruRU', 'В Дол', 'Поговорите с распорядительницей Ви Вин в святилище Семи Звезд в Вечноцветущем доле.', 'Я давно жду тебя, $gпутник:путница;.$B$BХотелось бы встретиться при иных обстоятельствах, но боюсь, что ситуация в Вечноцветущем доле крайне тяжелая.$B$BОбсудим это позже, а пока отправляйся к распорядительнице Ви Вин в святилище Семи Звезд.$B$BОна поможет тебе обустроиться.', '', '', '', '', '', '', 45114),
(30458, 'ruRU', 'Возвращение разведчиков', 'Поговорите с Реллом Ночным Ветром в Деревне Жемчужного Плавника в Нефритовом лесу.', '$n, твои друзья вернулись из разведки и хотят немедленно тебя видеть!$B$BБоюсь, что...$B$BХотя, пожалуй, не стоит опережать события. Ты $gсам:сама; все увидишь.', '', '', '', '', '', '', 45114),
(30312, 'ruRU', 'Второй шанс', 'Исцелите 6 раненых защитников.', 'Какие-то глупцы попытались прорваться на Золотую лестницу с востока, но были обстреляны пушками. Немногие уцелели в этой мясорубке, а те, кто выжил, вернулись домой с тяжелыми ранениями. Все поле битвы усеяно трупами и ранеными.$B$BВот, возьми эти бинты и помоги пострадавшим защитникам добраться до укреплений. Если тебе известны какие-нибудь исцеляющие заклинания, используй их. Только поторопись, у нас мало времени.', '', '', '', '', '', '', 45114),
(30310, 'ruRU', 'Гром в небесах', 'Убейте 3-х покоренных змеев.', 'Могу сломили волю небесных змеев и обернули их против нас.$B$BНаши защитники с ними вряд ли справятся, а вот ты – да. Иди на северо-запад к Золотой лестнице и подбей этих змеев.', '', '', '', '', '', '', 45114),
(30307, 'ruRU', 'Вечный дозор', 'Убейте 8 могу Шао-Тень на Золотой террасе.', 'Хорошо, что ты с нами, |3-6($c). Если хочешь присоединиться к битве, мне как раз нужен кто-то, чтобы очистить Золотую лестницу от нападающих могу.$B$BЯ могу рассчитывать на тебя?', '', '', '', '', '', '', 45114),
(29895, 'ruRU', 'По следу Белой Пешки', 'Покажите плащ адмиралу Тейлору в Деревне Жемчужного Плавника в Нефритовом лесу.', 'Плащ давно превратился в лохмотья, однако его отличный покрой и королевский герб не заметить нельзя.$B$BВам нужно показать эту вещь вашему командиру из Альянса.', '', '', '', '', '', '', 45114),
(28040, 'ruRU', 'Требуются герои: Мародон', 'Поговорите с духом Зейтара.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит немедленно явиться в Мародон, расположенный в западных Пустошах!$B$BИсцеление Мародона от поразившей его скверны положительно повлияло бы на Пустоши в целом! Если вы решите откликнуться на этот призыв, отправляйтесь в Мародон и обратитесь к духу Зейтара, который даст вам дальнейшие указания.', '', '', '', '', '', '', 45114),
(28023, 'ruRU', 'Требуются герои: Монастырь Алого ордена', 'Войдите в Монастырь Алого ордена.', 'Его королевское величество Андуин Ринн взывает ко всем годным к службе искателям приключений с просьбой незамедлительно направиться в Монастырь Алого ордена, что к северо-востоку от Подгорода!$B$BНеоднократные попытки переговоров с Алым орденом оказались безуспешными. Эти фанатики творят бесчинства не только в захваченных Чумных землях, но и на других территориях.$b$bОтправляйтесь в Монастырь Алого ордена и станьте орудием правосудия короля! Применение грубой силы приветствуется!', '', '', '', '', '', '', 45114),
(28021, 'ruRU', 'Требуются герои: Залы Алого ордена', 'Войдите в Залы Алого ордена.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит незамедлительно явиться в Залы Алого ордена, что к северо-востоку от Подгорода!$B$BДеятельность крестоносцев уже охватывает не только Чумные земли, но и другие территории. Его Величество опасается новой волны движения. Нельзя позволять фанатикам Алого ордена бесчинствовать на границах королевских земель!$b$bВойдите в Залы Алого ордена и нападите на оружейную и библиотеку прежде, чем они смогут мобилизовать свои силы.', '', '', '', '', '', '', 45114),
(28014, 'ruRU', 'Требуются герои: лабиринты Иглошкурых', 'Явитесь к Ольду Каменному Копью.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит немедленно явиться в лабиринты Иглошкурых, что на южной окраине Южных степей!$B$BОльду Каменному Копью требуется ваша помощь, чтобы не дать свинобразам распространиться по всей округе! Если вы решите откликнуться на этот призыв, отправляйтесь в лабиринты Иглошкурых и окажите Ольду Каменному Копью, мудрому почтенному шаману, всю необходимую помощь для предотвращения угрозы.', '', '', '', '', '', '', 45114),
(28013, 'ruRU', 'Требуются герои: Гномреган', 'Поговорите с Мерд-Доком.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит немедленно явиться в Гномреган, к западу от Стальгорна!$B$BГномы намерены отбить свой город, и им нужна помощь! Если вы решите откликнуться на этот призыв, отправляйтесь в Гномреган и поговорите с Мерд-Доком. Он набирает бойцов в команду \"Г\".', '', '', '', '', '', '', 45114),
(28012, 'ruRU', 'Требуются герои: тюрьма Штормграда', 'Явитесь с докладом к командиру стрелков Коу.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит немедленно явиться в тюрьму Штормграда, что в столице Его высочества!$B$BВ тюрьме произошел бунт! Если вы решите откликнуться на этот призыв, отправляйтесь к командиру стрелков Коу, старшему стрелку тюремной стражи, и помогите утихомирить бунтарей.', '', '', '', '', '', '', 45114),
(28011, 'ruRU', 'Требуются герои: Непроглядная Пучина', 'Поговорите с часовым Алувин.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит немедленно явиться в Непроглядную Пучину, что к западу от Астранаара!$B$BТам собрались служители культа Сумеречного Молота, действия которых угрожают всему миру! Если вы решите откликнуться на этот призыв, отправляйтесь в Непроглядную Пучину и поговорите с часовым Алувин, которая возглавляет силы ночных эльфов в этом регионе. Помогите справиться с угрозой Сумеречного Молота.', '', '', '', '', '', '', 45114),
(28009, 'ruRU', 'Требуются герои: крепость Темного Клыка', 'Поговорите с вожаком стаи Иваром Кровавым Клыком.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит немедленно явиться в крепость Темного Клыка, расположенную в южной части Серебряного бора.$B$BГнусный предатель лорд Годфри дорого заплатит за то, что он сделал с нашими новыми союзниками! Если вы решите откликнуться на этот призыв, отправляйтесь в крепость Темного Клыка и поговорите с вожаком стаи Иваром Кровавым Клыком. Он командует тамошним войском и жаждет мести.', '', '', '', '', '', '', 45114),
(28005, 'ruRU', 'Требуются герои: Мертвые копи', 'Поговорите с лейтенантом Горацио Лейном.', 'По повелению короля Андуина Ринна всем отважным искателям приключений надлежит явиться в Мертвые копи, что в южной части Западного края!$B$BНеобходимо избавить эти земли от угрозы, исходящей от возрожденного братства Справедливости! Если вы решите откликнуться на этот призыв, отправляйтесь в Мертвые копи, поговорите с лейтенантом Горацио Лейном, который занимается этим делом, и помогите ему разобраться с братством раз и навсегда.', '', '', '', '', '', '', 45114),
(14169, 'ruRU', 'Благодарный покойник', 'Принесите поминальный хлеб веселому духу дренея на кладбище Экзодара.$B$BЧтобы увидеть дух, используйте оранжевые бархатцы.', 'Как приятно было навестить друзей и родных! Только, кажется, я немного перестаралась... и съела все, что они приготовили для меня! Даже крошки подмела!$B$BМогу ли я попросить тебя принести мне еще вкусного поминального хлеба? Я была бы очень благодарна!$B$BКажется, рецепт можно купить у Чепмана.', '', '', '', '', '', '', 45114),
(12817, 'ruRU', 'Нападение Плети на Экзодар', 'Соберите три тусклых некротических камня созданий Плети, бродящих вокруг Экзодара, и изучите светящиеся рунические круги вокруг лагеря, после чего вернитесь к лейтенанту Крегору.', 'Армия нежити Короля-лича уже стоит у наших ворот. Мы не должны оставаться в стороне! Долг каждого солдата – защищать Экзодар от проклятых захватчиков до последней капли крови!$b $bВидишь эти странные рунические круги вокруг лагеря? Они пропитаны той же энергией, что окружает нежить и Некрополь. Ты $gдолжен:должна; выяснить, что они обозначают. Подойди к ним поближе, очисть местность от мерзких созданий Плети и приступай к исследованиям. И не забудь – я достойно вознагражу тебя за результаты, равно как и за доказательства твоей победы над Плетью. Иди же, не медли!', 'Осмотреть круг', '', '', '', '', '', 45114),
(11179, 'ruRU', 'У Финлея кишка тонка', 'Соберите 7 безупречных кишечных струн туманных саблезубов для Финлея Флетчера из Крепости Западной Стражи.', 'У нас так много лучников! И кто же должен следить за состоянием их оружия? Я, Финлей Флетчер!$B$BКомандир приказал мне и моим помощникам подготовить Крепость Диккор к походу, а у меня не было времени выбраться наружу и добыть кишечные струны, из которых изготавливается тетива. $B$B$C, $gмиленький:миленькая;, принеси мне несколько кишечных струн! Их можно добыть с туманных саблезубов, которые бродят возле фьорда. Только не тащи какие попало – мне подойдут только самые лучшие! Рваные кишки никуда не годятся.', '', '', '', '', '', '', 45114),
(10130, 'ruRU', 'Западный фланг', 'Убейте 10 стражников, 10 берсерков и 5 послушников клана Изувеченной Длани. О выполнении задания доложите лейтенанту Амади, которая будет ждать вас в западной сторожевой башне Оплота Чести.', 'Орки Скверны получили новый приказ – готовить войска и боевую технику к наступлению.$B$BОплот Чести хотят зажать в тиски и армия боевого командира Некрогга должна сформировать западный фланг.$B$BЕсли Оплот атакуют с запада, когда гарнизон будет занят обороной восточных стен, то вряд ли мы сумеем отбиться. Единственная наша надежда – вывести из строя западный фланг еще до начала сражения.', '', '', '', '', '', '', 45114),
(9695, 'ruRU', 'Повеление Солнечного короля', 'Доставьте повеление Солнечного короля воздаятелю Боросу на Кровавую заставу.', 'Похоже, это важный документ. Жаль только, что он написан на талассийском – ведь ты не знаешь этого языка, верно?$B$BБудем надеяться, воздаятель Борос подскажет, что делать с этим письмом.', '', '', '', '', '', '', 45114);

